import{t as e}from"./series-ehn-ogBq.js";var t=(e,t)=>({who:e,text:t}),n=t(`anika`,`Brilliant running. Ease right back now and get your breath.`),r=t(`anika`,`You got there, and that is what counts. Ease right back now.`),i=t(`kip`,`[excited] You lost them! Ease right back now.`),a=t(`kip`,`Okay, you are clear. Breathe. Ease right back now.`),o=t(`anika`,`Halfway. Keep going.`),s=t(`kip`,`Halfway! Keep it up!`),c=t(`anika`,`Easy now. Save your legs. It is a long night.`),l=(e,t,c,l,u,d={})=>({at:e,kind:`surge`,seconds:t,who:c,say:l,recover:u,success:c===`kip`?i:n,okay:c===`kip`?a:r,half:c===`kip`?s:o,...d}),u={id:`signal`,title:`The Parkes Signal`,blurb:`A signal from deep space, a talking capsule in the wheat, and a runner caught in the middle.`,note:`The story is set on a dark country night. In real life, run where you are well lit and easy to see.`,narrator:`signal-narrator`,score:`signal`,isNew:!0},d=[{id:`signal-contact`,episode:1,next:`Next time on The Parkes Signal: something lands in the wheat, a swarm takes off, and an army convoy rolls in.`,saga:`signal`,title:`First Contact`,series:`thriller`,type:`surge`,minutes:20,difficulty:`Gentle`,blurb:`Episode 1. The big dish catches a signal, every phone goes black, and three silent lights stop right above you.`,loop:t(`kip`,`You closed a loop. I have marked it on my paper map. Old school.`),early:t(`anika`,`Stopping there is fine. The drive made it, thanks to you. Get some rest. The signal will keep.`),beats:[{at:3,kind:`recover`,seconds:200,chapter:`Nine fourteen pm`,scene:`outback`,say:`Parkes, in the Central West. A clear cold night, a sky full of stars, and the big dish turning slowly in its paddock. Start with an easy walk or jog.`},{at:40,kind:`story`,spatial:`dog`,say:`A farm dog barks at nothing. Then it stops, mid bark, and the whole paddock goes quiet.`},{at:75,kind:`story`,fx:`transmission`,say:`Then you hear it. A pulse of sound from nowhere. Every streetlight flickers. Every phone screen goes black.`},{at:140,kind:`story`,who:`anika`,say:`Dr Anika Rao, at the dish. Do not panic. But maybe walk a bit faster. We just caught a signal, and it is not from anything we know.`},{at:205,kind:`story`,who:`kip`,say:`Kip here, on the old ham radio in my ute. Phones are out, internet is out, but this thing is older than my dad. It still works.`},l(260,30,`anika`,`The signal knocked out the dish computers. I need the backup drive from the visitor centre. Pick it up for 30 seconds and go!`,120,{chapter:`The visitor centre`,fx:`servo`}),{at:330,kind:`story`,say:`The visitor centre is dark. A cardboard astronaut grins at you from the corner. The backup drive sits on the desk, blinking green.`},{at:380,kind:`quiz`,who:`anika`,say:`While you are there. In 1969, this dish helped beam live TV of which Moon landing to the world?`,options:[{key:`A`,label:`Apollo 11`},{key:`B`,label:`Apollo 13`},{key:`C`,label:`Voyager 1`}],answer:`A`,right:t(`anika`,`Apollo 11. Hundreds of millions of people watched, and a lot of it came through this paddock.`),wrong:t(`anika`,`It was Apollo 11. Hundreds of millions of people watched, and a lot of it came through this paddock.`)},{at:450,kind:`story`,fx:`scan`,say:`Overhead, three lights slide across the stars. No sound. No blinking. Perfectly in a line.`},{at:500,kind:`story`,who:`kip`,say:`[whispers] Are you seeing the lights? They stopped. They are right above you. I reckon they are watching.`},{at:560,kind:`choice`,id:`lights`,who:`anika`,say:`The lights are drifting toward the wheat. Follow them, or stay on the road and bring me the drive?`,options:[{key:`A`,label:`Follow the lights`,flag:`followed`,say:t(`kip`,`[excited] Legend. Keep them in sight. I am right with you on the radio.`)},{key:`B`,label:`Stay on the road`,flag:`road`,say:t(`anika`,`Sensible. The drive first, then we chase lights.`)}],default:`B`,timeout:t(`anika`,`Stay on the road. Drive first.`)},l(630,30,`kip`,`They are speeding up! Pick it up for 30 seconds along the fence line. Keep them in sight!`,120,{if:`followed`,chapter:`The lights`,fx:`whoosh`}),l(631,30,`anika`,`The lights are following you! Pick it up for 30 seconds, straight down the road to the dish.`,120,{unless:`followed`,chapter:`The lights`,fx:`whoosh`}),{at:720,kind:`story`,if:`followed`,say:`The lights stop over the wheat and hang there, humming. Then, one by one, they blink out. The paddock is dark again.`},{at:721,kind:`story`,unless:`followed`,say:`You glance back. The lights are right behind you, keeping pace. Then, one by one, they blink out.`},{at:790,kind:`steady`,seconds:160,scene:`dish`,say:`You reach the dish. It towers over you, sixty four metres across, groaning as it turns. Settle into an easy pace while Anika works.`,easyNudge:c},{at:860,kind:`story`,who:`anika`,fx:`transmission`,say:`The drive works. I am playing the signal back. Listen. Two pulses. Three. Five. Seven. It is counting in prime numbers.`},{at:930,kind:`story`,who:`kip`,say:`Prime numbers. So it is not a satellite glitch. Something out there can count, and it wants us to know.`},l(990,30,`anika`,`It is sending something new. Coordinates! Pick it up for 30 seconds while I decode.`,130,{chapter:`The coordinates`,fx:`riser`}),{at:1060,kind:`story`,who:`anika`,fx:`braam`,say:`[whispers] Wait. These coordinates are not in space. They are here, in Parkes. They are exactly where you are standing.`},{at:1120,kind:`finale`,say:`Episode one complete. The signal is counting, the lights are gone, and something is coming to find you. To be continued.`}]},{id:`signal-swarm`,episode:2,previously:`Previously on The Parkes Signal: a signal from deep space, three silent lights, and coordinates pointing right at you.`,next:`Next time on The Parkes Signal: a meteor shower, a race to the dish, and a choice the whole world will hear.`,saga:`signal`,title:`The Swarm`,series:`thriller`,type:`surge`,minutes:25,difficulty:`Steady effort`,blurb:`Episode 2. A capsule in the wheat says hello, a swarm of drones takes off, and the army wants what you are holding.`,loop:t(`kip`,`Another loop closed. The swarm is copying your route. I think they like you.`),early:t(`anika`,`That will do for tonight. The core is safe with Kip. You did plenty.`),beats:[{at:3,kind:`recover`,seconds:240,chapter:`Midnight`,scene:`outback`,say:`Midnight. Frost on the fence posts and your breath in the air. Something landed in the wheat ten minutes ago. Warm up easy.`},{at:50,kind:`story`,fx:`sonic`,say:`A boom rolls across the paddocks, so deep you feel it in your ribs.`},{at:75,kind:`story`,spatial:`dog`,say:`A farm dog starts barking. Then another. Then every dog for ten kilometres joins in.`},{at:130,kind:`story`,who:`kip`,say:`Kip here. I followed the glow. There is a crater in Bob Fenwick’s wheat, and something in it is humming.`},{at:190,kind:`story`,who:`anika`,say:`Do not touch anything. I am on my way with the scanner. Tell me what you see.`},{at:245,kind:`story`,say:`In the middle of the crater sits a capsule the size of a fridge. Smooth and silver, warm to the touch, glowing a soft blue.`},{at:300,kind:`story`,who:`lumen`,fx:`transmission`,say:`[curious] Hello. I am Lumen. I have come a very long way. You are the one who runs. I have been listening.`},{at:370,kind:`story`,who:`kip`,say:`[excited] It talks! The fridge talks! Anika, the fridge is talking to us!`},l(430,45,`anika`,`The capsule is opening and something is coming out. Pick it up for 45 seconds and get some distance!`,130,{chapter:`The swarm`,scene:`swarm`,fx:`braam`}),{at:530,kind:`story`,spatial:`drones`,say:`A swarm of tiny silver drones pours out, hundreds of them, glittering in the moonlight. They circle you once. Then again.`},{at:590,kind:`story`,who:`lumen`,say:`Do not be alarmed. My scouts are curious. They follow anything quick, and you are very quick.`},{at:650,kind:`puzzle`,who:`anika`,say:`Lumen says the scouts will settle if we answer its question. It is counting again. Two, three, five, seven. What comes next?`,options:[{key:`A`,label:`9`},{key:`B`,label:`11`},{key:`C`,label:`13`}],answer:`B`,right:t(`anika`,`Eleven, the next prime. The swarm just slowed right down. Clever.`),wrong:t(`anika`,`It is 11, the next prime. I have sent it. The swarm just slowed right down.`)},{at:720,kind:`steady`,seconds:200,say:`The swarm hangs over the wheat, humming softly like bees on a warm day. Hold an easy pace and catch your breath.`,easyNudge:c},{at:780,kind:`quiz`,who:`lumen`,say:`[curious] I have a question for you, runner. What do you call your galaxy?`,options:[{key:`A`,label:`Andromeda`},{key:`B`,label:`The Milky Way`},{key:`C`,label:`Orion`}],answer:`B`,right:t(`lumen`,`The Milky Way. A lovely name. From the outside, it looks like spilled sugar.`),wrong:t(`lumen`,`You call it the Milky Way. A lovely name. From the outside, it looks like spilled sugar.`)},{at:850,kind:`story`,who:`kip`,fx:`scan`,say:`Uh oh. Headlights on the highway. Lots of them. Army trucks, I reckon. Somebody else heard the signal.`},{at:910,kind:`story`,who:`hale`,say:`This is Major Dan Hale. This area is closed. Whoever is in that paddock, stay exactly where you are.`},{at:965,kind:`story`,who:`lumen`,say:`[whispers] They want to take my core. Without it, I cannot call home. Please. Help me hide it.`},{at:1020,kind:`choice`,id:`hide`,who:`anika`,say:`Lumen has given you its core. It is warm and the size of a cricket ball. Hide in the old silo, or down by the creek?`,options:[{key:`A`,label:`The old silo`,flag:`silo`,say:t(`kip`,`The silo. Good thinking. Steel walls. Their scanners will not see through them.`)},{key:`B`,label:`Down by the creek`,flag:`creek`,say:t(`anika`,`The creek. The cold water will hide its heat. Go.`)}],default:`B`,timeout:t(`anika`,`Down by the creek. Go now.`)},l(1080,45,`kip`,`Trucks are coming up the track! Pick it up for 45 seconds and get to the silo!`,130,{if:`silo`,chapter:`Hide`,fx:`screech`}),l(1081,45,`anika`,`Trucks are coming up the track! Pick it up for 45 seconds, down the hill to the creek!`,130,{unless:`silo`,chapter:`Hide`,fx:`screech`}),{at:1180,kind:`story`,if:`silo`,say:`You slip inside the silo. It smells of old wheat. Through the rusty gaps, searchlights sweep the paddock and move on.`},{at:1181,kind:`story`,unless:`silo`,say:`You crouch by the creek under the river red gums. Searchlights sweep across the water and move on.`},{at:1240,kind:`story`,spatial:`helicopter`,say:`A helicopter thunders overhead, searchlight blazing. The swarm scatters into the dark like sparks from a campfire.`},l(1300,45,`kip`,`The searchlight is swinging back! Pick it up for 45 seconds and get to my ute!`,120,{chapter:`The ute`,fx:`rotor`}),{at:1400,kind:`story`,who:`kip`,say:`In! Go, go, go! Seatbelt on. Hold the core. Do not drop the core. Please do not drop the core.`},{at:1450,kind:`finale`,say:`Episode two complete. You have the core, the Major has the capsule, and Lumen has one night left to call home. To be continued.`}]},{id:`signal-starfall`,episode:3,previously:`Previously on The Parkes Signal: a talking capsule, a swarm of drones, and a glowing core hidden in your hands.`,next:`Next time on The Parkes Signal: one little scout stayed behind, a salvage company wants it, and Parkes is full of Elvises.`,saga:`signal`,title:`Starfall`,series:`thriller`,type:`surge`,minutes:30,difficulty:`Hard effort`,blurb:`Episode 3. A meteor shower, a race to the dish, and four minutes to help a lost visitor call home.`,loop:t(`lumen`,`You closed another loop. From up here, your paths look like a constellation.`),early:t(`anika`,`Stopping there is fine. Kip can carry the core the rest of the way. You got us so close.`),beats:[{at:3,kind:`recover`,seconds:300,chapter:`Two in the morning`,scene:`outback`,say:`Two in the morning. Kip’s ute is parked behind a hay shed. The core glows softly in your hands. Warm up easy.`},{at:60,kind:`story`,who:`lumen`,say:`[sighs] My family’s ship passes this world once every hundred years. Tonight, at three. If the big dish sends my song, they will hear me.`},{at:130,kind:`story`,who:`anika`,say:`So we need the dish, the core and four minutes of transmission. And Major Hale has the dish surrounded.`},{at:200,kind:`story`,spatial:`meteor`,say:`A streak of white light tears across the sky. Then another. Then ten more. A meteor shower, right on cue.`},{at:260,kind:`quiz`,who:`kip`,say:`[excited] Quick one while we wait. Lumen wants to know about our neighbourhood. How many planets go round our Sun?`,options:[{key:`A`,label:`7`},{key:`B`,label:`8`},{key:`C`,label:`9`}],answer:`B`,right:t(`lumen`,`Eight. Thank you. I will tell my family. They will like the one with the rings.`),wrong:t(`kip`,`It is 8. Pluto got moved to the dwarf planet list. Lumen says it will like the one with the rings.`)},l(330,60,`anika`,`Hale’s trucks are moving! Pick it up for 60 seconds, across the paddock, toward the dish!`,140,{chapter:`The run to the dish`,scene:`dish`,fx:`siren`}),{at:440,kind:`story`,spatial:`meteor`,say:`Meteors rain down over the dish, silver and gold. It looks like the whole sky is cheering you on.`},{at:500,kind:`story`,who:`hale`,say:`Runner, I can see you on the thermal camera. I am not your enemy. I just need to know what that thing is.`},{at:560,kind:`puzzle`,who:`lumen`,say:`The control room door wants a code. It is how long sunlight takes to reach your world. About how long is that?`,options:[{key:`A`,label:`8 seconds`},{key:`B`,label:`8 minutes`},{key:`C`,label:`8 hours`}],answer:`B`,right:t(`lumen`,`About 8 minutes. The door is open. Your star is very punctual.`),wrong:t(`anika`,`It is about 8 minutes. Typing it in now. The door is open.`)},{at:640,kind:`steady`,seconds:220,say:`You are inside. The control room hums and blinks. Hold an easy pace while Anika wakes up the dish.`,easyNudge:c},{at:700,kind:`story`,who:`anika`,fx:`servo`,say:`Dish is turning. Slowly. Come on, old girl. You did Apollo. You can do this.`},{at:780,kind:`story`,who:`kip`,say:`[whispers] Major Hale is outside the door. Just him. He has taken his helmet off. He wants to talk to you.`},{at:850,kind:`choice`,id:`share`,who:`anika`,say:`Hale says the signal should be kept quiet, for safety. Give him a copy, or share it with every observatory on Earth?`,options:[{key:`A`,label:`Give it to Hale`,flag:`hale`,say:t(`hale`,`Thank you. I will make sure the right people hear this. Properly, and safely.`)},{key:`B`,label:`Share it with the world`,flag:`world`,say:t(`anika`,`Every observatory on Earth. Sending it now. Nobody gets to keep the sky a secret.`)}],default:`B`,timeout:t(`anika`,`Sharing it with everyone. The sky belongs to all of us.`)},{at:920,kind:`story`,if:`hale`,who:`hale`,say:`Right. Then my soldiers will hold the gate. Nobody stops this transmission. You have my word.`},{at:921,kind:`story`,if:`world`,who:`hale`,say:`[sighs] I cannot argue with that. My soldiers will hold the gate. Nobody stops this transmission.`},l(990,60,`kip`,`Power is dropping! The backup generator is at the far gate. Pick it up for 60 seconds!`,140,{chapter:`Power`,fx:`alarm`}),{at:1100,kind:`story`,fx:`thunk`,say:`You haul on the big lever. The generator coughs, splutters, then roars. Every light on the dish blazes white.`},{at:1160,kind:`story`,who:`anika`,say:`Power is back. Dish is locked on. Ninety seconds until the ship passes. Get the core up to the feed cabin!`},l(1220,60,`anika`,`Up the ladder to the feed cabin! Pick it up for 60 seconds. This is it!`,150,{chapter:`Three o’clock`,scene:`swarm`,fx:`riser`}),{at:1330,kind:`story`,who:`lumen`,fx:`transmission`,say:`[whispers] Thank you, runner. Sending now. Listen.`},{at:1370,kind:`story`,fx:`braam`,say:`The dish sings. A deep note you feel in your chest. High above, a light far bigger than a star slows down, and stops.`},{at:1430,kind:`story`,spatial:`drones`,say:`The swarm rises from the wheat, thousands of them, and forms a shape in the sky. It is a runner. It is you.`},{at:1490,kind:`story`,who:`lumen`,say:`My family heard me. They are coming to take me home. I will tell them about the little blue world, and the one who runs.`},{at:1550,kind:`steady`,seconds:180,scene:`outback`,chapter:`Dawn`,say:`The great light fades back into the stars. Cool down now with a gentle jog or a walk. The sky is quiet again.`},{at:1640,kind:`story`,who:`kip`,fx:`cheer`,say:`Mate. We just helped an alien phone home. From Parkes. Nobody at the pub is going to believe this.`},{at:1700,kind:`story`,who:`hale`,say:`For the record, you are the bravest civilian I have ever met. And easily the fastest.`},{at:1760,kind:`finale`,who:`anika`,say:`Episode three complete. Lumen is going home, and the dish did it again. But in Kip’s shed, something small just beeped. To be continued.`,fx:`chirp`}]},{id:`signal-stowaway`,episode:4,previously:`Previously on The Parkes Signal: a meteor shower, a race to the dish, and Lumen sent safely home.`,next:`Next time on The Parkes Signal: a lost ship, the darkest sky in Australia, and one last run up a mountain.`,saga:`signal`,title:`Stowaway`,series:`thriller`,type:`surge`,minutes:30,difficulty:`Hard effort`,blurb:`Episode 4. A tiny drone left behind, a salvage company that wants it, and a chase through a town full of Elvises.`,loop:t(`kip`,`Loop closed! Sprocket beeped twice. I think that is a high five.`),early:t(`anika`,`Stopping there is fine. Sprocket is safe with Kip tonight. You did plenty.`),beats:[{at:3,kind:`recover`,seconds:300,chapter:`A month later`,scene:`outback`,say:`A month later. A warm January night in Parkes, and the whole town is buzzing. Warm up easy.`},{at:50,kind:`story`,fx:`chirp`,say:`From Kip’s shed comes a sound you know. A chirp. A glow under the door. Something in there is awake.`},{at:110,kind:`story`,who:`kip`,say:`[excited] Okay, do not freak out. One of Lumen’s scouts stayed behind. I named it Sprocket. It likes Vegemite and hates the vacuum.`},{at:170,kind:`story`,who:`anika`,say:`Kip. You have been hiding an alien drone in your shed for a month? [sighs] Of course you have.`},{at:230,kind:`story`,who:`vance`,say:`Good evening. Margot Vance, Quorum Salvage. We track unusual signals. And your shed, Mr Kip, is very unusual.`},{at:290,kind:`story`,fx:`scan`,say:`A black van rolls up the street, lights off. On its roof, a dish turns slowly toward the shed.`},l(340,45,`kip`,`They are coming in! Grab Sprocket and go out the back. Pick it up for 45 seconds!`,130,{chapter:`The shed`,fx:`servo`}),{at:440,kind:`story`,spatial:`drones`,say:`Behind you, Quorum’s drones lift off the van. Big ones, grey and clumsy. Sprocket chirps at them, deeply offended.`},{at:500,kind:`quiz`,who:`kip`,say:`Good news, we can hide in a crowd. Parkes holds a huge Elvis Festival every year. Which month is it on?`,options:[{key:`A`,label:`January`},{key:`B`,label:`July`},{key:`C`,label:`October`}],answer:`A`,right:t(`kip`,`January. And tonight the whole main street is full of Elvises. Hundreds of them.`),wrong:t(`kip`,`It is January. And tonight the whole main street is full of Elvises. Hundreds of them.`)},{at:570,kind:`steady`,seconds:200,scene:`festival`,say:`You slip into the main street. Sequins, sideburns and big gold sunglasses everywhere. Hold an easy pace and blend in.`,easyNudge:c},{at:640,kind:`story`,spatial:`chatter`,say:`A man in a white jumpsuit hands you a pair of sunglasses. Thank you, thank you very much, he says, and winks.`},{at:700,kind:`choice`,id:`hide`,who:`anika`,say:`Sprocket needs a hiding spot. Tuck it in a sequinned Elvis cape, or up on the parade float with the giant guitar?`,options:[{key:`A`,label:`The Elvis cape`,flag:`cape`,say:t(`kip`,`[laughs] Sprocket in sequins. Best disguise ever. It is glowing with pride.`)},{key:`B`,label:`The parade float`,flag:`float`,say:t(`anika`,`The float. Nobody looks twice at one more shiny thing on a float.`)}],default:`B`,timeout:t(`anika`,`The float. Quick.`)},{at:770,kind:`story`,who:`vance`,say:`Scanning. Elvis. Elvis. Elvis. [sighs] Why are they all Elvis?`},l(830,45,`anika`,`The scanner is getting close! Pick it up for 45 seconds and stay with the cape crowd!`,130,{if:`cape`,chapter:`The parade`,fx:`riser`}),l(831,45,`kip`,`The scanner is getting close! The float is moving. Pick it up for 45 seconds and keep up with it!`,130,{unless:`cape`,chapter:`The parade`,fx:`riser`}),{at:940,kind:`story`,fx:`cheer`,say:`The parade band kicks off. Hundreds of Elvises sway at once. The Quorum drones circle, completely lost.`},{at:1e3,kind:`puzzle`,who:`anika`,say:`Sprocket is beeping in binary. One, then zero, then one. One zero one in binary is what number?`,options:[{key:`A`,label:`3`},{key:`B`,label:`5`},{key:`C`,label:`101`}],answer:`B`,right:t(`anika`,`Five. It is counting down. Five what, though? Five minutes?`),wrong:t(`anika`,`It is 5. A four, no two, and a one. It is counting down. Five minutes?`)},{at:1070,kind:`story`,who:`hale`,say:`Major Hale. I hear you have company. I am parked behind the bowling club. Get to me and Quorum will not follow.`},l(1130,60,`kip`,`Vance has spotted the glow! Down the lane to the bowling club. Pick it up for 60 seconds!`,150,{chapter:`The bowling club`,scene:`outback`,fx:`screech`}),{at:1250,kind:`story`,fx:`thunk`,say:`A car door swings open. You dive in. Hale pulls away slowly, perfectly legally, while the van spins its wheels in the gravel.`},{at:1310,kind:`story`,who:`vance`,say:`[sarcastic] Very clever. But that drone is calling home, Major. Anyone can listen. I just listen better.`},{at:1370,kind:`story`,who:`hale`,say:`She is not wrong. Whatever it is sending, we are not the only ones who can hear it.`},l(1430,60,`anika`,`Hale’s road is blocked. Out of the car and across the paddock to the dish. Pick it up for 60 seconds!`,150,{chapter:`Back to the dish`,scene:`dish`,fx:`alarm`}),{at:1550,kind:`story`,fx:`chirp`,say:`Inside the control room, Sprocket floats up off your palm and spins slowly. A beam of blue light spills out of it.`},{at:1610,kind:`story`,who:`lumen`,fx:`transmission`,say:`[whispers] Runner. It is Lumen. Our ship was damaged in the meteor storm. We are lost. Sprocket can guide us, from the darkest sky you have.`},{at:1680,kind:`steady`,seconds:160,chapter:`Star map`,say:`A map of stars fills the room, turning slowly around you. Cool down with a gentle jog or a walk while Anika reads it.`},{at:1760,kind:`story`,who:`anika`,say:`Darkest sky in Australia. Warrumbungle National Park. A few hours north. Kip, fuel up the ute.`},{at:1820,kind:`finale`,who:`vance`,say:`[mischievously] The Warrumbungles. Thank you, Major. I will see you all there. Episode four complete. To be continued.`,fx:`braam`}]},{id:`signal-home`,episode:5,previously:`Previously on The Parkes Signal: a stowaway drone called Sprocket, a town full of Elvises, and a lost ship that needs a guide.`,saga:`signal`,title:`Homeward`,series:`thriller`,type:`surge`,minutes:35,difficulty:`Hard effort`,blurb:`Episode 5, the finale. The darkest sky in Australia, a race up a mountain, and a little drone that wants to go home.`,loop:t(`lumen`,`Another loop. Sprocket draws it in the sky for us. It looks like a smile.`),early:t(`anika`,`That will do. Hale can carry Sprocket the last stretch. You brought it so far.`),beats:[{at:3,kind:`recover`,seconds:300,chapter:`The Warrumbungles`,scene:`ranges`,say:`Midnight in the Warrumbungles. Jagged peaks against the stars, and the sky so dark you can see your shadow by starlight. Warm up easy.`},{at:60,kind:`story`,spatial:`owl`,say:`An owl calls from the trees. Mopoke. Mopoke. Sprocket chirps back, very politely.`},{at:120,kind:`quiz`,who:`anika`,say:`Here is why we came. In 2016, this park became Australia’s first what?`,options:[{key:`A`,label:`Dark Sky Park`},{key:`B`,label:`Marine Park`},{key:`C`,label:`Space Port`}],answer:`A`,right:t(`anika`,`Dark Sky Park. No city glow for miles. Perfect for stargazing, and for guiding ships.`),wrong:t(`anika`,`It became Australia’s first Dark Sky Park. No city glow for miles. Perfect for guiding ships.`)},{at:190,kind:`story`,who:`lumen`,say:`Runner, the ship is close but blind. Sprocket must shine from the highest point, at exactly half past two. Not before. Not after.`},{at:250,kind:`story`,who:`kip`,say:`Highest point we can reach is the mountain with the observatory domes. Long climb. Good thing you are a runner.`},l(310,45,`anika`,`Headlights on the road behind us. That is Quorum. Pick it up for 45 seconds and get onto the walking track!`,130,{chapter:`The track`,fx:`screech`}),{at:410,kind:`story`,spatial:`drones`,say:`Quorum’s grey drones sweep the treetops, searchlights stabbing between the gums. Sprocket dims itself to a tiny blue dot.`},{at:470,kind:`story`,who:`hale`,say:`Hale here. My team is holding the road. Quorum will have to come up on foot. You have a head start. Use it.`},{at:530,kind:`steady`,seconds:200,say:`The track winds up through the bush. Hold an easy pace and save your legs. It is a long way up.`,easyNudge:c},{at:600,kind:`story`,who:`vance`,say:`[curious] Runner, can you hear me? Quorum would pay you very well for that little drone. Very, very well.`},{at:660,kind:`choice`,id:`vance`,who:`anika`,say:`Vance wants to talk. Ignore her and keep climbing, or tell her what Sprocket really is: a kid trying to get home?`,options:[{key:`A`,label:`Keep climbing`,flag:`ignore`,say:t(`kip`,`Radio off. Legs on. I like it.`)},{key:`B`,label:`Tell her the truth`,flag:`truth`,say:t(`vance`,`[sighs] A lost kid. That is not in my briefing. Let me think about that.`)}],default:`A`,timeout:t(`kip`,`Radio off. Keep climbing.`)},l(730,60,`kip`,`Switchbacks! Quorum is on the track below us. Pick it up for 60 seconds!`,150,{chapter:`Switchbacks`,fx:`footsteps`}),{at:850,kind:`story`,fx:`sonic`,say:`A boom rolls over the ranges. High above, a star that is not a star blinks once, then slides sideways.`},{at:910,kind:`story`,who:`lumen`,fx:`transmission`,say:`[excited] They can feel Sprocket now. They are coming down. Twenty minutes, runner. Hurry.`},{at:970,kind:`puzzle`,who:`anika`,say:`Sprocket needs a star to aim by. The Southern Cross on our flag. How many stars does it have?`,options:[{key:`A`,label:`4`},{key:`B`,label:`5`},{key:`C`,label:`7`}],answer:`B`,right:t(`anika`,`Five. Sprocket has locked onto the Cross. Aiming now.`),wrong:t(`anika`,`It has 5 on the flag. Sprocket has locked onto the Cross. Aiming now.`)},l(1040,60,`anika`,`Rock steps to the summit. Pick it up for 60 seconds. We are nearly there!`,150,{chapter:`The summit`,scene:`swarm`,fx:`riser`}),{at:1160,kind:`story`,fx:`impact`,say:`You burst out onto the summit. White observatory domes glow under the stars. The whole sky is enormous.`},{at:1220,kind:`story`,if:`truth`,who:`vance`,say:`Runner. I have sent my drones home. And I have told my bosses the signal was a weather balloon. Go on. Get the kid home.`},{at:1221,kind:`story`,unless:`truth`,who:`hale`,say:`Quorum just turned back. Vance says the signal was a weather balloon. [laughs] I think somebody had a change of heart.`},{at:1290,kind:`quiz`,who:`kip`,say:`Two minutes to wait. Lumen asked me this one. What is the closest star to our Sun?`,options:[{key:`A`,label:`Sirius`},{key:`B`,label:`Proxima Centauri`},{key:`C`,label:`Betelgeuse`}],answer:`B`,right:t(`lumen`,`Proxima Centauri. Our home is much further. But tonight, it feels close.`),wrong:t(`kip`,`It is Proxima Centauri. Lumen says home is much further than that. Tonight, it feels close.`)},l(1360,60,`anika`,`Half past two! Hold Sprocket up and run the summit ridge so the ship can see the light move. Pick it up for 60 seconds!`,150,{chapter:`Half past two`,fx:`transmission`}),{at:1480,kind:`story`,fx:`braam`,say:`Sprocket blazes like a tiny sun. Above you, a ship the size of a town slides out of the stars, silent, glowing, and slows to a stop.`},{at:1540,kind:`story`,spatial:`drones`,say:`Thousands of scouts pour down from the ship and swirl around the summit, chirping. Sprocket chirps back. It is home.`},{at:1600,kind:`story`,who:`lumen`,say:`My family thanks you, runner. Sprocket wants to give you something. Hold out your hand.`},{at:1660,kind:`story`,fx:`chirp`,say:`Sprocket drops a pebble into your palm. Smooth, warm and faintly blue. Then it zips up into the light and is gone.`},{at:1720,kind:`steady`,seconds:180,chapter:`Dawn`,scene:`ranges`,say:`The ship fades into the stars. The first grey light touches the peaks. Cool down now with a gentle jog or a walk.`},{at:1810,kind:`story`,who:`kip`,say:`My shed is so quiet now. [sighs] I am going to miss that little guy. And his Vegemite habit.`},{at:1870,kind:`story`,who:`hale`,say:`Officially, nothing happened tonight. Unofficially, it was the best night of my career.`},{at:1930,kind:`finale`,who:`anika`,say:`The Parkes Signal is complete. Sprocket is home, the sky is quiet, and somewhere up there, a family knows your name. Look up sometimes.`}]}],f=[`signal-contact`,`signal-swarm`,`signal-starfall`,`signal-stowaway`,`signal-home`],p=(e,t)=>({who:e,text:t}),ee=p(`jo`,`Great running. Ease right back now and catch your breath.`),m=p(`jo`,`You got there, and that is what counts. Ease right back now.`),te=p(`ollie`,`Copy that, you made it. Brilliant. Ease right back now.`),ne=p(`ollie`,`Copy, you made it. Good stuff. Ease right back now.`),h=p(`jo`,`Halfway. Stay with it.`),g=p(`jo`,`Steady. Runners who pace themselves last all day. Ease back a touch.`),_=(e,t,n,r,i,a={})=>({at:e,kind:`surge`,seconds:t,who:n,say:r,success:n===`ollie`?te:ee,okay:n===`ollie`?ne:m,recover:i,...a}),re=p(`viv`,`[mischievously] Clean getaway. Ease right back now.`),v=p(`viv`,`Bit close, but you are clear. Ease right back now.`),y=p(`pixel`,`[excited] You lost them! Ease right back now.`),b=p(`pixel`,`Okay, you are clear. Breathe. Ease right back now.`),x=p(`viv`,`Halfway. Keep moving.`),S=p(`viv`,`Easy. Nobody notices a jogger. Everybody notices a sprinter.`),C=(e,t,n,r,i,a={})=>({at:e,kind:`surge`,seconds:t,who:n,say:r,success:n===`pixel`?y:re,okay:n===`pixel`?b:v,recover:i,...a}),ie=[...e.map(e=>e.SAGA),u,{id:`ember`,title:`Ember Run`,blurb:`Wattle Creek is burning and the phones are down. The brigade needs a runner.`,note:`Includes bushfire scenes. It is a story: on a real fire day, follow your local fire service and skip the run if there is smoke.`,narrator:`ember-narrator`,score:`ember`},{id:`heist`,title:`The Night Job`,blurb:`A crooked developer, a forged deed and a crew that needs a runner.`,narrator:`heist-narrator`,score:`heist`}],ae=[{id:`ember-smoke`,episode:1,next:`Next time on Ember Run: the wind turns, embers fall on the main street, and Bluey needs a hand.`,saga:`ember`,title:`Smoke on the Ridge`,series:`thriller`,type:`surge`,minutes:20,difficulty:`Gentle`,blurb:`Episode 1. Smoke on the ridge, no phone signal, and a lane full of people who need to hear the warning.`,loop:p(`jo`,`You have closed a loop. That patch is checked and clear. Good work.`),early:p(`jo`,`Calling it there is fine. Banksia Lane got the warning, thanks to you. Rest up.`),beats:[{at:3,kind:`recover`,seconds:200,chapter:`A hot northerly`,scene:`bush`,say:`Wattle Creek. Forty one degrees, a hot northerly, and cicadas so loud you can feel them. Start with an easy walk or jog.`},{at:35,kind:`story`,spatial:`helicopter`,say:`Above you, a spotting helicopter thuds over the ridge, low and fast. Everyone on the street looks up.`},{at:60,kind:`story`,fx:`downer`,say:`Up on the ridge, a thin grey line of smoke is rising. It was not there an hour ago.`},{at:130,kind:`story`,who:`jo`,say:`Captain Jo Harker, Wattle Creek brigade. The mobile tower is down, so we need runners. That is you. Welcome aboard.`},{at:200,kind:`story`,who:`ollie`,say:`Ollie here in the comms van. Fire is about twenty k out. No panic. We are just getting people ready.`},_(260,30,`jo`,`First job. Banksia Lane has not heard the warning. Pick it up for 30 seconds and get there before the wind does.`,120,{chapter:`Banksia Lane`,scene:`smoke`,fx:`siren`}),{at:330,kind:`story`,who:`gwen`,say:`[curious] Oh, hello love. Gwen Patterson. A fire, you say? Well, I am not leaving without my chooks. All six of them.`},{at:400,kind:`choice`,id:`chooks`,who:`jo`,say:`Gwen will not budge without her chooks. Your call. Carry the cage to the ute yourself, or radio Bluey to swing by?`,options:[{key:`A`,label:`Carry the cage`,flag:`carried`,say:p(`gwen`,`[laughs] Oh, you are a dear. Mind the speckled one. She bites.`)},{key:`B`,label:`Radio Bluey`,flag:`radioed`,say:p(`ollie`,`Copy. Bluey is two minutes out with the ute. Good thinking.`)}],default:`B`,timeout:p(`jo`,`No time to wait. I have radioed Bluey myself.`)},_(470,30,`ollie`,`Wind is picking up. Two more houses at the top of the lane. Pick it up for 30 seconds.`,120),{at:560,kind:`story`,who:`bluey`,say:`G'day. Bluey Walsh. I have got eight horses, a float and a chook cage. I will run them all down to the oval. No worries.`},{at:610,kind:`story`,if:`carried`,who:`gwen`,say:`Love, I should tell you. The speckled one is called Margaret, and I think she likes you.`},{at:611,kind:`story`,unless:`carried`,who:`bluey`,say:`Chooks are in the cage, cage is in the ute, and the speckled one has already had a go at me. Beauty.`},{at:640,kind:`steady`,seconds:160,say:`The lane is empty now. Smoke drifts over the gum trees. Settle into an easy pace and head back to the station.`,easyNudge:g},{at:720,kind:`story`,spatial:`firetruck`,say:`A fire truck screams past, lights flashing, heading for the ridge. The wind shoves hard at your back.`},{at:760,kind:`story`,who:`ollie`,say:`Ollie here. Strike team says the fire just jumped Wattle Creek Road. That was not supposed to happen.`},{at:810,kind:`story`,who:`ollie`,say:`Ollie here. Evacuation centre is the footy oval. Everyone from Banksia Lane has checked in. Six chooks included.`},_(880,30,`ember-narrator`,`A low rumble rolls down the valley. Then an orange glow on the ridge. Pick it up for 30 seconds to the station.`,150,{chapter:`The glow`,fx:`braam`}),{at:950,kind:`story`,say:`Ash starts to fall like grey snow. It catches in your eyelashes and settles on your shoulders.`},{at:1030,kind:`story`,who:`jo`,say:`[sighs] Good work today. But that glow means it is coming. Get some rest. Tomorrow, the wind changes.`},{at:1085,kind:`quiz`,who:`jo`,say:`Quick one before you rest. On a Catastrophic fire danger day, what is the safest plan?`,options:[{key:`A`,label:`Stay and defend`},{key:`B`,label:`Leave early`}],answer:`B`,right:p(`jo`,`Spot on. Leave early. Houses can be rebuilt. People cannot.`),wrong:p(`jo`,`Not quite. On a Catastrophic day, the safest plan is to leave early. Houses can be rebuilt.`)},{at:1140,kind:`finale`,say:`Episode one complete. Banksia Lane is safe, the chooks are in the ute, and the ridge is still glowing. To be continued.`}]},{id:`ember-wind`,episode:2,previously:`Previously on Ember Run: smoke on the ridge, a lane cleared just in time, and six very cross chooks.`,next:`Next time on Ember Run: no power, no radio, a lost dog, and a long climb in the dark.`,saga:`ember`,title:`The Wind Change`,series:`thriller`,type:`surge`,minutes:25,difficulty:`Steady effort`,blurb:`Episode 2. A southerly is coming at three. Embers in the main street, a blown tyre and a brigade without maps.`,loop:p(`jo`,`Loop closed. That block is checked for spot fires. Nice running.`),early:p(`jo`,`Good call to stop. The maps got through and the main street is holding. We will take it from here.`),beats:[{at:3,kind:`recover`,seconds:220,chapter:`Three o’clock`,scene:`smoke`,say:`Day two. The sky is the colour of milky tea and the sun is a red coin. Warm up easy.`},{at:80,kind:`story`,who:`jo`,say:`Listen up. A southerly change hits at three. When it does, the fire turns and runs straight at town.`},{at:120,kind:`story`,spatial:`helicopter`,say:`Two water bombing helicopters thunder overhead toward the dam, buckets swinging underneath.`},{at:160,kind:`story`,who:`ollie`,say:`The strike team at the dam has no maps and the radio keeps dropping out. They need paper maps. By hand.`},{at:205,kind:`choice`,id:`dam`,who:`jo`,say:`That is your job. Maps in your pocket. Two ways to the dam: the fire trail, steep but short, or the main road, longer but flat?`,options:[{key:`A`,label:`The fire trail`,flag:`trail`,say:p(`jo`,`Fire trail it is. Steep, so short steps up the hill.`)},{key:`B`,label:`The main road`,flag:`road`,say:p(`jo`,`Main road. Longer, so settle into it.`)}],default:`B`,timeout:p(`jo`,`Take the main road. It is the safer bet.`)},_(240,null,`jo`,`Up the fire trail. Pick it up for 200 metres to the top of the hill.`,150,{if:`trail`,metres:200,chapter:`The dam road`,half:h}),_(241,45,`jo`,`Along the main road. Pick it up for 45 seconds and get those maps to the dam.`,150,{unless:`trail`,chapter:`The dam road`,half:h}),{at:330,kind:`story`,say:`Through the haze, a fire truck. A firefighter leans out, grabs the maps and gives you a thumbs up.`},{at:420,kind:`story`,who:`bluey`,say:`[sighs] Bluey here. Blown a tyre on the float. The horses are fine, they think it is a picnic. Can you run for a jack?`},_(500,45,`bluey`,`The servo on the corner has one. Pick it up for 45 seconds and bring it back.`,150,{half:h}),{at:590,kind:`story`,who:`bluey`,say:`[laughs] Beauty. Tyre is on. Eight horses, one very relieved bloke. See you at the oval.`},{at:640,kind:`story`,who:`ollie`,say:`All units, hold. The wind just swung. I repeat, the wind has swung.`},{at:680,kind:`story`,who:`ollie`,say:`Uh oh. The change has come early. Wind is swinging round. Embers are landing on the main street.`,fx:`whoosh`,scene:`fire`,chapter:`Ember attack`},_(760,45,`jo`,`Spot fires near the bakery. Pick it up for 45 seconds and tell the crew where they are.`,150,{fx:`siren`,half:h}),{at:850,kind:`story`,fx:`flare`,say:`Hoses hiss. Steam rises off the bakery gutter. The crew knocks down every spot fire you point at.`},{at:940,kind:`steady`,seconds:240,say:`Hold an easy pace and sweep the back streets. Look for glowing embers in gutters and doormats.`,easyNudge:g},{at:1e3,kind:`story`,spatial:`firetruck`,say:`Another truck races by, siren wailing. Smoke rolls down the main street like fog off the sea.`},{at:1020,kind:`quiz`,who:`jo`,say:`While you sweep, a question. How far ahead of a fire front can embers start new spot fires?`,options:[{key:`A`,label:`About 50 metres`},{key:`B`,label:`Several kilometres`}],answer:`B`,right:p(`jo`,`Right. Embers ride the wind for kilometres. That is why we sweep the back streets.`),wrong:p(`jo`,`Further than that. Embers can fly several kilometres ahead. That is why we sweep the back streets.`)},{at:1100,kind:`story`,who:`gwen`,say:`Is that you, love? The chooks are cross about the smoke, but they are safe. Thank you for coming back for us.`},_(1200,45,`ollie`,`One more ember run. The old hall has a doormat smouldering. Pick it up for 45 seconds.`,150,{half:h}),{at:1290,kind:`story`,say:`A crack, then a fizz. Down the street, a power line sags and the lights of Wattle Creek flicker.`,fx:`crack`,chapter:`Lights out`},{at:1330,kind:`story`,who:`jo`,say:`If that repeater goes, we are blind out here. Ollie, talk to me.`},{at:1380,kind:`story`,who:`ollie`,say:`Jo, the repeater is losing power. If it goes, we lose the radio. Jo, do you copy? Jo?`},{at:1460,kind:`finale`,say:`Static. Then nothing. Episode two complete. The town is dark, and the radio has gone quiet. To be continued.`,fx:`squelch`}]},{id:`ember-tower`,episode:3,previously:`Previously on Ember Run: the wind turned, the main street held, and then the lights went out.`,next:`Next time on Ember Run, the final episode: a stuck bus, a fire front at midnight, and a long run to morning.`,saga:`ember`,title:`Blackout`,series:`thriller`,type:`surge`,minutes:30,difficulty:`Steady effort`,blurb:`Episode 3. No power, no radio, and a lost dog. The old fire lookout on the hill holds the only way to call for help.`,loop:p(`jo`,`Loop closed. That ground is checked. You are a natural at this.`),early:p(`jo`,`Fair call. You got us halfway to the lookout. Bluey will take the ute the rest of the way.`),beats:[{at:3,kind:`recover`,seconds:240,chapter:`In the dark`,scene:`night`,say:`Night. No power, no phones, no radio. Just torches, a red sky, and the hum of a generator at the oval. Warm up easy.`},{at:90,kind:`story`,who:`jo`,say:`Here is the plan. The old fire lookout on Mount Bellamy has a backup radio. Get it on and we can talk to the water bombers.`},{at:130,kind:`story`,spatial:`dog`,say:`Somewhere in the dark, a dog barks and barks. Every house on this street is empty and black.`},{at:180,kind:`story`,who:`pip`,say:`Excuse me. I am Pip. Have you seen a little brown dog? His name is Pickles. He ran off when the lights went out.`},{at:250,kind:`choice`,id:`pickles`,who:`jo`,say:`Your call. Search the bracken for Pickles now, or head straight up the hill and look on the way down?`,options:[{key:`A`,label:`Search for Pickles now`,flag:`search`,say:p(`pip`,`Thank you! He likes squeaky noises. And cheese.`)},{key:`B`,label:`Head straight up`,flag:`climb`,say:p(`jo`,`Good. The radio first. Pickles will turn up, dogs always do.`)}],default:`B`,timeout:p(`jo`,`Radio first. Off you go.`)},{at:330,kind:`steady`,seconds:240,chapter:`Mount Bellamy road`,say:`Follow the fire trail up through the stringybarks. Easy pace. Your torch makes the smoke glow.`,easyNudge:g},{at:400,kind:`quiz`,who:`jo`,say:`Bush quiz while we climb. Which tree often waits for a fire to open its seed pods?`,options:[{key:`A`,label:`Banksia`},{key:`B`,label:`Jacaranda`},{key:`C`,label:`Fig`}],answer:`A`,right:p(`jo`,`Banksia. Many need the heat of a fire to open their cones. The bush comes back after, every time.`),wrong:p(`jo`,`It is the Banksia. Many need the heat of a fire to open their cones. The bush comes back after, every time.`)},{at:470,kind:`story`,if:`search`,say:`Something rustles in the bracken. Two bright eyes. A tail, wagging very hard.`,fx:`thunk`},{at:540,kind:`story`,if:`search`,who:`pip`,say:`[excited] Pickles! You found him! Thank you, thank you. He is licking everything. Sorry.`},_(600,null,`jo`,`The trail gets steep from here. Pick it up for 300 metres to the first switchback.`,150,{metres:300,chapter:`The climb`,half:h}),{at:680,kind:`story`,fx:`crack`,say:`A branch cracks off a stringybark and crashes across the trail behind you. Too close. Keep moving.`},{at:760,kind:`story`,say:`Below you, Wattle Creek is a scatter of torches. Above you, the lookout tower is black against the orange sky.`},_(840,null,`jo`,`Second switchback. Pick it up for 300 metres. You are nearly there.`,150,{metres:300,half:h}),{at:920,kind:`story`,spatial:`helicopter`,say:`Far off, a helicopter with a searchlight sweeps the ridge, hunting for spot fires in the dark.`},{at:1e3,kind:`story`,say:`The lookout door is stiff. You lean on it. It gives with a groan.`,fx:`thunk`},_(1070,null,`jo`,`Last stretch. Up the tower stairs and the hill behind it. Pick it up for 300 metres.`,150,{metres:300,half:h}),{at:1230,kind:`story`,say:`An old radio. A big red switch. You flick it, and the lights blink on. Now it needs the right channel.`,fx:`click`,chapter:`Hello, Wattle Creek`},{at:1250,kind:`puzzle`,say:`A note is taped to the radio in Jo’s writing. Brigade channel: chooks plus horses. Gwen has six chooks and Bluey has eight horses. Which channel?`,options:[{key:`A`,label:`Channel 12`},{key:`B`,label:`Channel 14`},{key:`C`,label:`Channel 16`}],answer:`B`,right:`Channel 14. You turn the dial, and the static clears.`,wrong:`Six chooks and eight horses makes channel 14. You turn the dial, and the static clears.`},{at:1290,kind:`story`,who:`ollie`,fx:`cheer`,say:`[excited] Is that the lookout? Wattle Creek comms, reading you loud and clear. You legend!`},{at:1370,kind:`steady`,seconds:240,say:`Head back down the trail at an easy pace. Let the legs recover. The night is not over yet.`,easyNudge:g},{at:1450,kind:`story`,unless:`search`,say:`Halfway down, something rustles in the bracken. Two bright eyes. A tail, wagging very hard.`,fx:`thunk`},{at:1520,kind:`story`,unless:`search`,who:`pip`,say:`[excited] Pickles! You found him on the way down! Thank you. He is licking everything. Sorry.`},_(1620,60,`ollie`,`Water bombers are coming at first light. Pick it up for 60 seconds back to the oval.`,120),{at:1720,kind:`story`,who:`ollie`,say:`Uh oh. Jo, the last school bus from Ridge Road has stalled. Eleven people on board and the front is getting closer.`},{at:1790,kind:`finale`,say:`Episode three complete. The radio is back, Pickles is home, and a bus is stuck on Ridge Road. To be continued.`,fx:`boom`}]},{id:`ember-dawn`,episode:4,previously:`Previously on Ember Run: the radio is back, Pickles is home, and a bus full of people is stuck on Ridge Road.`,next:`Next time on Ember Run: three months on, the storm season arrives, the creek rises fast, and Pip and Pickles are on the wrong side.`,saga:`ember`,title:`The Long Night`,series:`thriller`,type:`surge`,minutes:35,difficulty:`Hard effort`,blurb:`Episode 4. A stalled bus, a fire front at midnight, and a long run to the morning.`,loop:p(`jo`,`Loop closed. Another patch of Wattle Creek, checked and safe.`),early:p(`jo`,`That is plenty. The bus is moving and the crews have the line. You have done your bit tonight.`),beats:[{at:3,kind:`recover`,seconds:300,chapter:`Ridge Road`,scene:`night`,say:`Midnight on Ridge Road. A yellow bus, hazard lights blinking, eleven worried faces at the windows. Warm up easy.`},{at:50,kind:`story`,spatial:`firetruck`,say:`Sirens everywhere now. Trucks from three towns over, all heading for the creek.`},{at:100,kind:`story`,who:`jo`,say:`The bus is not broken, just stuck. A fallen branch is blocking the road. You run ahead, we clear the way.`},{at:200,kind:`story`,who:`bluey`,say:`Bluey here. I have got a chainsaw and a bad attitude towards branches. Show me where they are.`},{at:255,kind:`choice`,id:`bus`,who:`jo`,say:`Two ways to the oval. The creek road is shorter but smoky. The ridge road is longer but clear. Which way do you lead the bus?`,options:[{key:`A`,label:`The creek road`,flag:`creek`,say:p(`jo`,`Creek road. Stay low, stay quick.`)},{key:`B`,label:`The ridge road`,flag:`ridge`,say:p(`jo`,`Ridge road. Longer, but the driver can see where they are going.`)}],default:`B`,timeout:p(`jo`,`We will take the ridge road. Clear air matters.`)},_(300,60,`jo`,`Run ahead and find the next branch. Pick it up for 60 seconds.`,120,{chapter:`Clearing the way`,half:h,fx:`siren`}),{at:390,kind:`story`,say:`A chainsaw roars. Wood splits. The bus rolls forward with a hiss of air brakes.`,fx:`crack`},_(450,60,`jo`,`Another one round the bend. Pick it up for 60 seconds.`,120,{half:h}),_(600,60,`ollie`,`Smoke is thick near the creek. The driver needs you as a guide light. Pick it up for 60 seconds.`,120,{if:`creek`,half:h}),_(601,60,`ollie`,`The ridge road climbs, and the bus is slowing. Be its guide light up the hill. Pick it up for 60 seconds.`,120,{unless:`creek`,half:h}),{at:690,kind:`story`,who:`pip`,say:`Pickles and I are watching from the oval. Everyone is cheering for the bus. Go, go, go!`},{at:760,kind:`story`,say:`The bus pulls into the oval. Eleven people step off. Somebody hugs the driver. Somebody hugs you.`,chapter:`The front`},{at:840,kind:`steady`,seconds:300,scene:`fire`,say:`Now the front arrives. The crews hold the line at the creek. Run easy laps round the oval, and stay ready.`,easyNudge:g},{at:980,kind:`story`,who:`jo`,say:`This is it. Every crew on the creek line. We hold here and the town holds. Stay with me.`},{at:1050,kind:`story`,fx:`flare`,say:`A wall of orange rises behind the creek line. You can feel the heat on your face from three hundred metres away.`},{at:1100,kind:`story`,fx:`flare`,say:`The roar is enormous. Embers stream overhead like orange snow. The sprinklers on the oval hiss.`},{at:1150,kind:`story`,who:`jo`,say:`Hold. Hold the line. Do not give it an inch.`},_(1200,60,`jo`,`Spot fire on the grandstand roof. Pick it up for 60 seconds and get the hose crew.`,120,{half:h,fx:`siren`}),_(1350,60,`jo`,`Another, by the canteen. Pick it up for 60 seconds.`,120,{half:h}),{at:1440,kind:`story`,who:`gwen`,say:`Love, the chooks have stopped fussing. Do you feel that? The wind is dropping.`,chapter:`First light`},{at:1480,kind:`quiz`,who:`pip`,say:`Pip has a question for you. In New South Wales, what do the letters R F S stand for?`,options:[{key:`A`,label:`Rural Fire Service`},{key:`B`,label:`Regional Fire Station`},{key:`C`,label:`Rapid Fire Squad`}],answer:`A`,right:p(`pip`,`[excited] Yes! The Rural Fire Service. Pickles wants to join.`),wrong:p(`pip`,`It is the Rural Fire Service! My uncle is in it. Pickles wants to join.`)},{at:1530,kind:`story`,say:`A deep thudding in the grey dawn. Water bombers, low over the ridge, one after another.`,fx:`rotor`},_(1620,60,`ollie`,`Bombers have the head of the fire. One last run, Jo needs you at the creek line. Pick it up for 60 seconds.`,180,{half:h}),{at:1700,kind:`story`,scene:`rain`,fx:`thunder`,say:`Then, a sound nobody expected. Pattering on tin roofs. Rain. Real rain. People step out with their faces turned up.`},{at:1750,kind:`story`,spatial:`magpie`,say:`And then, impossibly, a magpie starts to sing.`},{at:1800,kind:`story`,who:`jo`,say:`[sighs] The front is out. Every person in Wattle Creek is safe. We lost the old hall roof. We will build a better one.`},{at:1890,kind:`story`,who:`bluey`,say:`Horses are fine. Gwen is fine. And mate, one of her chooks just laid an egg. In the middle of all this. Legend.`},{at:1970,kind:`story`,say:`Cool down now with a gentle jog or a walk. Breathe in that wet bush smell.`},{at:2080,kind:`finale`,say:`Episode four complete. Wattle Creek made it through. Here is to every real volunteer who runs towards the smoke. To be continued.`}]},{id:`ember-flood`,episode:5,previously:`Previously on Ember Run: a bus on Ridge Road, a fire front at midnight, and a town that made it through to morning.`,saga:`ember`,title:`The Big Wet`,series:`thriller`,type:`surge`,minutes:35,difficulty:`Hard effort`,blurb:`Episode 5, the finale. A storm on the burnt hills, a creek rising by the minute, and eight scouts on the wrong side of the water.`,loop:p(`jo`,`Loop closed. Another street checked and clear of water.`),early:p(`jo`,`That will do. The SES has the rest. You got the word out, and that is what matters.`),beats:[{at:3,kind:`recover`,seconds:300,chapter:`Three months later`,scene:`rain`,say:`Three months later. The hills around Wattle Creek are green again, just. Today the sky is the colour of a bruise. Warm up easy.`},{at:50,kind:`story`,fx:`thunder`,say:`Thunder cracks right overhead. Fat drops smack the road, and steam rises off the hot bitumen.`},{at:110,kind:`story`,who:`jo`,say:`Runner! Good to have you back. Huge storm cell, and the burnt hills cannot soak up the water. The creek is going to rise fast.`},{at:170,kind:`story`,who:`ollie`,say:`Ollie here, back in the comms van. Bad news. Lightning just hit the new phone tower. So, you know. Runners again.`},{at:230,kind:`quiz`,who:`jo`,say:`Quick refresher before we start. A road ahead is under water. What do you do?`,options:[{key:`A`,label:`Drive through slowly`},{key:`B`,label:`Turn around`},{key:`C`,label:`Wade in to check`}],answer:`B`,right:p(`jo`,`Spot on. If it is flooded, forget it. Fast water is far stronger than it looks.`),wrong:p(`jo`,`Turn around and find another way. If it is flooded, forget it. Fast water is far stronger than it looks.`)},_(300,45,`jo`,`The low bridge on Creek Street is about to go under. Pick it up for 45 seconds and stop the traffic before it does.`,130,{chapter:`Creek Street`,scene:`flood`,half:h,fx:`rush`}),{at:400,kind:`story`,spatial:`car`,say:`A ute slows, then stops. The driver sees brown water churning over the bridge, and turns around. You did that.`},{at:460,kind:`story`,who:`gwen`,say:`[laughs] Oh, it is you again, love! The chooks are on the kitchen table and the water is at the back step. Margaret is furious.`},{at:520,kind:`choice`,id:`gwen`,who:`jo`,say:`Gwen’s yard is flooding. Carry the chooks up to the church hall yourself, or fetch Bluey and his tractor?`,options:[{key:`A`,label:`Carry the chooks`,flag:`chooks`,say:p(`gwen`,`Margaret remembers you, love. She is very nearly pleased.`)},{key:`B`,label:`Fetch Bluey`,flag:`tractor`,say:p(`bluey`,`On my way with the old Massey. A bit of water is no bother to her.`)}],default:`B`,timeout:p(`jo`,`I have called Bluey. Tractor is coming.`)},_(590,45,`jo`,`Up the hill to the church hall with a cage of very cross chooks. Pick it up for 45 seconds!`,130,{if:`chooks`,half:h,fx:`thunder`}),_(591,45,`ollie`,`Bluey is stuck behind a fallen branch on Banksia Lane. Pick it up for 45 seconds and guide him round!`,130,{unless:`chooks`,half:h,fx:`crack`}),{at:690,kind:`story`,if:`chooks`,say:`You set the cage down in the church hall. Six chooks, one runner, and a very wet minister handing out cups of tea.`},{at:691,kind:`story`,unless:`chooks`,who:`bluey`,say:`Found a way round, thanks to you. Gwen, the chooks and the kettle are all in the tractor bucket. Up we go.`},{at:750,kind:`steady`,seconds:220,scene:`rain`,say:`The rain settles into a steady roar on every tin roof in town. Hold an easy pace along the high road while Ollie checks the gauges.`,easyNudge:g},{at:820,kind:`story`,who:`ollie`,fx:`beeps`,say:`Creek gauge just jumped half a metre in ten minutes. Something upstream has let go. A jam of fallen logs, maybe.`},{at:890,kind:`story`,who:`pip`,say:`[excited] It is Pip! Pickles and me are at the scout hall. The water is coming under the door and Pickles will not stop barking!`},{at:950,kind:`story`,who:`jo`,say:`The scout hall is on the low side of the creek, and the bridge is under. The footbridge at the weir is the only way across.`},{at:1010,kind:`puzzle`,who:`ollie`,say:`The weir gate has a code padlock. The tag says: the emergency number, typed twice. What is the code?`,options:[{key:`A`,label:`911911`},{key:`B`,label:`000000`},{key:`C`,label:`999999`}],answer:`B`,right:p(`ollie`,`Triple zero, twice. Six zeros. The padlock clicks open.`),wrong:p(`ollie`,`It is 000000. Triple zero, twice. The padlock clicks open.`)},_(1080,60,`jo`,`Across the footbridge to the scout hall. Water is lapping at the planks. Pick it up for 60 seconds, and watch your feet!`,150,{chapter:`The weir`,scene:`flood`,half:h,fx:`rush`}),{at:1200,kind:`story`,fx:`creak`,say:`The footbridge shudders under you. Brown water roars a metre below. Then you are across, and the scout hall door flies open.`},{at:1260,kind:`story`,who:`pip`,say:`You came! Pickles, look, it is the runner! [laughs] He is licking your knees. That means thank you.`},{at:1320,kind:`story`,who:`jo`,say:`Eight scouts, two leaders and one very happy dog. The water is still rising. Everyone up to high ground, now.`},{at:1380,kind:`choice`,id:`route`,who:`ollie`,say:`Two ways up. The bush track behind the hall is steep but dry. The road is longer and floods in places. Which way?`,options:[{key:`A`,label:`The bush track`,flag:`track`,say:p(`jo`,`Bush track. Kids in the middle, leaders at the back. Go.`)},{key:`B`,label:`The long road`,flag:`road`,say:p(`ollie`,`Long road it is. I will tell you where the water is.`)}],default:`A`,timeout:p(`jo`,`Bush track. Go.`)},_(1440,60,`jo`,`Lead the line up the bush track. Steady, and nobody falls behind. Pick it up for 60 seconds!`,150,{if:`track`,chapter:`High ground`,half:h,fx:`footsteps`}),_(1441,60,`ollie`,`Lead them up the long road. Keep to the middle, away from the water. Pick it up for 60 seconds!`,150,{unless:`track`,chapter:`High ground`,half:h,fx:`footsteps`}),{at:1560,kind:`story`,spatial:`helicopter`,say:`A rescue helicopter thunders over the ridge, its spotlight sweeping the water. The scouts cheer and wave their hats.`},{at:1620,kind:`story`,fx:`boom`,say:`Below you, the old weir footbridge breaks free and spins away down the creek. You crossed it eleven minutes ago.`},{at:1680,kind:`story`,who:`jo`,say:`Everyone is on high ground. Every single person. Ollie, call it in.`},{at:1740,kind:`story`,who:`ollie`,fx:`cheer`,say:`Copy that, Captain. Wattle Creek, all accounted for. Even the chooks. Especially the chooks.`},{at:1800,kind:`steady`,seconds:180,chapter:`After the storm`,scene:`bush`,say:`The storm rolls east. Sun breaks through, and steam rises off the green hills. Cool down now with a gentle jog or a walk.`},{at:1900,kind:`story`,who:`gwen`,say:`Love, there is a sausage sizzle at the hall on Saturday. For you. Margaret has agreed to attend.`},{at:1970,kind:`story`,who:`bluey`,say:`Fire, then flood. Reckon this town is tougher than both. [laughs] Same time next disaster? I hope not.`},{at:2040,kind:`finale`,who:`jo`,say:`Ember Run is complete. Through fire and flood, Wattle Creek stood together. Here is to every volunteer, in orange and in yellow.`}]},{id:`heist-recruit`,episode:1,next:`Next time on The Night Job: black tie, forty floors of stairs, and one very expensive safe.`,saga:`heist`,title:`The Recruit`,series:`thriller`,type:`surge`,minutes:20,difficulty:`Gentle`,blurb:`Episode 1. A stranger at the fish markets, a parcel that must not be followed, and a job offer.`,loop:p(`viv`,`A loop. You doubled back on your own trail. Very professional.`),early:p(`viv`,`Stopping there is fine. You have shown me enough. I will be in touch.`),beats:[{at:3,kind:`recover`,seconds:200,chapter:`The fish markets`,scene:`city`,say:`Sydney. Ten past nine at night. The harbour is black glass and the city hums. Start with an easy walk or jog.`},{at:30,kind:`story`,spatial:`car`,say:`A car hisses past on the wet road. Then another. Then one that slows down, just a little too much.`},{at:70,kind:`story`,who:`viv`,say:`Do not turn around. My name is Viv. I need a runner, and I have been watching you. You are quick and nobody notices you.`},{at:150,kind:`story`,who:`viv`,say:`Here is an earpiece. Pop it in. Tonight is a test. Carry one parcel across The Rocks without being followed.`},{at:220,kind:`story`,who:`pixel`,say:`[excited] Hi! Pixel. I do the cameras and the clever bits. I can see you on six of them. Wave. No, do not wave.`},C(270,30,`pixel`,`Grey sedan, two streets back. That is Crane security. Pick it up for 30 seconds and lose them.`,120,{chapter:`The parcel`,fx:`footsteps`}),{at:320,kind:`story`,spatial:`car`,fx:`heartbeat`,say:`Headlights sweep across you. The grey sedan rolls by, slow. A face in the window turns to look.`},{at:350,kind:`story`,who:`viv`,say:`Who is Crane? Lachlan Crane. Property developer. He is about to bulldoze the Harbourside Pool with a deed he forged.`},{at:430,kind:`story`,who:`mack`,say:`Mack. I drive. Do not talk to me before coffee. Grey sedan is circling back towards Argyle Street.`},{at:470,kind:`choice`,id:`escape`,who:`viv`,say:`Two ways to lose him. Through the Argyle Cut and down the stairs, or over Observatory Hill and through the park?`,options:[{key:`A`,label:`The Argyle Cut`,flag:`cut`,say:p(`viv`,`The Cut. Old sandstone, lots of shadows. I like it.`)},{key:`B`,label:`Observatory Hill`,flag:`hill`,say:p(`viv`,`The hill. Nobody chases anyone uphill. Clever.`)}],default:`A`,timeout:p(`viv`,`Too slow. The Cut, now.`)},C(500,30,`viv`,`Through the Argyle Cut and down the steps. Pick it up for 30 seconds.`,120,{unless:`hill`}),C(501,30,`viv`,`Up Observatory Hill and through the park. Pick it up for 30 seconds.`,120,{if:`hill`}),{at:590,kind:`story`,who:`pixel`,say:`Lost them! He is stuck behind a garbage truck. I may have changed a traffic light. Allegedly.`},{at:620,kind:`story`,spatial:`chatter`,say:`You slip into a crowd spilling out of a pub. Nobody notices one more jogger.`},{at:660,kind:`steady`,seconds:160,say:`Blend in now. Easy pace along the wharves, like any other night jogger.`,easyNudge:S},{at:740,kind:`quiz`,who:`viv`,say:`A little test while you blend in. The Opera House opened in which year?`,options:[{key:`A`,label:`1959`},{key:`B`,label:`1973`},{key:`C`,label:`1988`}],answer:`B`,right:p(`viv`,`1973. Building started in 1959. Fourteen years. Good things take time. So do good plans.`),wrong:p(`viv`,`It opened in 1973. Building started in 1959. Fourteen years. Good things take time. So do good plans.`)},{at:830,kind:`story`,who:`viv`,say:`Open the parcel. Go on. Yes, it is a lamington. You passed the test before you even started.`},{at:860,kind:`quiz`,who:`viv`,say:`One last test. What do Sydneysiders call the Harbour Bridge?`,options:[{key:`A`,label:`The Coathanger`},{key:`B`,label:`The Paperclip`},{key:`C`,label:`The Big Arch`}],answer:`A`,right:p(`viv`,`The Coathanger. A local. Good.`),wrong:p(`viv`,`It is the Coathanger. Locals know. Now you do too.`)},C(900,30,`mack`,`Change of plan. Grey sedan is back and it is heading your way. Pick it up for 30 seconds to the van.`,150,{chapter:`The offer`,fx:`screech`}),{at:1e3,kind:`story`,spatial:`helicopter`,say:`A police helicopter drifts over the harbour. Not for you. Probably.`},{at:1040,kind:`story`,who:`viv`,say:`[whispers] Welcome to the crew. Tomorrow night, Crane throws a gala in his tower. The real deed is in his safe. We take it back.`},{at:1140,kind:`finale`,who:`crane`,say:`[sarcastic] Someone is asking questions about my deed. Find them. Episode one complete. To be continued.`,fx:`boom`}]},{id:`heist-gala`,episode:2,previously:`Previously on The Night Job: a stranger at the fish markets, a parcel, a lamington, and a job offer.`,next:`Next time on The Night Job: a silver briefcase, a bike chase, and a swap on the ferry wharf.`,saga:`heist`,title:`The Gala`,series:`thriller`,type:`surge`,minutes:25,difficulty:`Steady effort`,blurb:`Episode 2. Black tie on the top floor. Forty flights of service stairs. One safe.`,loop:p(`viv`,`Loop closed. You know this block better than his guards do now.`),early:p(`viv`,`Abort is fine. Always have an exit. Mack, bring the van round. We go again another night.`),beats:[{at:3,kind:`recover`,seconds:220,chapter:`Crane Tower`,scene:`city`,say:`Crane Tower. Glass and money, forty floors high. Tonight the top floor is a gala. Warm up easy.`},{at:80,kind:`story`,who:`viv`,say:`Plan is simple. I go in the front in a very nice dress. You go up the service stairs. Pixel opens doors. Mack waits.`},{at:160,kind:`story`,who:`pixel`,say:`Cameras on a loop in three, two, one. They are now watching yesterday. Yesterday was very boring.`,fx:`click`},{at:230,kind:`steady`,seconds:200,chapter:`The stairs`,scene:`tower`,say:`Into the stairwell. Easy, even pace. Forty floors is a long way, so save your legs.`,easyNudge:S},{at:330,kind:`story`,who:`reg`,say:`[sighs] Evening. Reg, night security. Twenty eight years in this building. Do not mind me, I am just checking the doors.`},{at:400,kind:`story`,fx:`creak`,say:`A door bangs somewhere above you. Footsteps on the stairs. Then nothing at all.`},C(450,45,`pixel`,`Reg is coming up the stairs behind you. Pick it up for 45 seconds to the next landing.`,150,{half:x,fx:`heartbeat`}),{at:540,kind:`story`,scene:`gala`,say:`The top floor. Music, champagne, a string quartet. Crane laughs too loudly at his own joke.`,chapter:`The gala`},{at:600,kind:`story`,spatial:`chatter`,say:`Laughter spills out of the ballroom. Two guests stroll past the stairwell door, arguing about yachts.`},{at:620,kind:`story`,who:`crane`,say:`[laughs] A pool! For the public! Can you imagine? No, this harbour deserves apartments. Very expensive apartments.`},{at:700,kind:`story`,who:`viv`,say:`[whispers] I have got his attention. His study is the second door on the left. Pixel, the lock.`},{at:735,kind:`choice`,id:`route`,who:`pixel`,say:`Two ways to the study. Through the kitchen, or straight across the dance floor?`,options:[{key:`A`,label:`Through the kitchen`,flag:`kitchen`,say:p(`pixel`,`Kitchen. Watch the trays. And the chef. Mostly the chef.`)},{key:`B`,label:`Across the dance floor`,flag:`dance`,say:p(`viv`,`[laughs] Bold. Smile at everyone.`)}],default:`A`,timeout:p(`pixel`,`Kitchen. Go, go.`)},C(770,45,`pixel`,`Lock is open, but a waiter is heading your way. Pick it up for 45 seconds through the study door.`,150,{half:x}),{at:845,kind:`story`,if:`dance`,say:`Someone spins you into a twirl on the way past. Crane claps along. He has no idea.`},{at:846,kind:`story`,unless:`dance`,say:`A chef hands you a sausage roll on the way through. You eat it. Of course you do.`},{at:860,kind:`story`,say:`The study. Leather chairs, a painting of Crane, and behind it, a safe.`,fx:`creak`,chapter:`The safe`},{at:930,kind:`puzzle`,who:`pixel`,say:`The safe wants a five letter word. His yacht is called Regal, and he uses his boat name backwards for everything. What is the code?`,options:[{key:`A`,label:`Lager`},{key:`B`,label:`Regal`},{key:`C`,label:`Galer`}],answer:`A`,right:p(`pixel`,`[laughs] Lager. Classy. Typing it in, and we are in.`),wrong:p(`pixel`,`Close. Regal backwards is Lager. Typing it in, and we are in.`)},{at:1e3,kind:`story`,say:`An old envelope. Inside, a deed dated nineteen oh two. The Harbourside Pool, gifted to the people of Sydney forever.`},C(1060,45,`viv`,`Alarm! Someone tripped it downstairs. Pick it up for 45 seconds to the stairwell.`,150,{fx:`alarm`,scene:`tower`,half:x}),{at:1100,kind:`story`,fx:`smash`,say:`Behind you, a waiter drops a whole tray of champagne glasses. Every head in the room turns. Perfect cover.`},{at:1150,kind:`story`,who:`reg`,say:`You. With the envelope. [sighs] My grandad built that pool. I did not see anything. Go.`},C(1230,45,`mack`,`Van is at the loading dock. Pick it up for 45 seconds and get in.`,150,{half:x}),{at:1290,kind:`story`,spatial:`firetruck`,say:`Sirens wail down on George Street. Coming this way, or just passing? Do not wait to find out.`},{at:1340,kind:`story`,scene:`city`,who:`pixel`,fx:`downer`,say:`Wait. Hold the envelope up to the light. Oh no. That watermark is from last year. It is a copy.`},{at:1440,kind:`finale`,who:`crane`,say:`[mischievously] Looking for this? The real deed never leaves my side. Episode two complete. To be continued.`,fx:`boom`}]},{id:`heist-cross`,episode:3,previously:`Previously on The Night Job: we cracked Crane’s safe, and found a copy. He has the real deed.`,next:`Next time on The Night Job, the final episode: one deed, one ferry, and a midnight deadline.`,saga:`heist`,title:`The Double Cross`,series:`thriller`,type:`surge`,minutes:30,difficulty:`Steady effort`,blurb:`Episode 3. Crane is moving the real deed to his yacht. A courier, a briefcase and a city in the way.`,loop:p(`viv`,`Loop closed. You are making a map of this city in your legs.`),early:p(`viv`,`Pull out, that is fine. Mack will tail the courier. Rest those legs for the big night.`),beats:[{at:3,kind:`recover`,seconds:240,chapter:`The briefcase`,scene:`street`,say:`Two nights later. Rain on the windscreen, the crew squashed in Mack’s van. Warm up easy.`},{at:90,kind:`story`,who:`viv`,say:`Crane thinks he won. Good. People who think they won get sloppy. He is moving the real deed to his yacht at Rose Bay.`},{at:170,kind:`story`,who:`pixel`,say:`His courier just left the tower with a silver briefcase. On foot. I have him on camera. Your turn.`},{at:240,kind:`steady`,seconds:180,say:`Follow at a distance. Easy pace, like you are just out for a run. Never closer than a block.`,easyNudge:S},{at:320,kind:`story`,spatial:`car`,say:`A taxi leans on its horn as the courier weaves through traffic. He does not look back.`},{at:380,kind:`quiz`,who:`pixel`,say:`He might be heading for a ferry. Quick, which wharf is the main ferry hub in Sydney?`,options:[{key:`A`,label:`Circular Quay`},{key:`B`,label:`Manly`},{key:`C`,label:`Barangaroo`}],answer:`A`,right:p(`pixel`,`Circular Quay. Most ferries start and end there. I am watching every gate.`),wrong:p(`pixel`,`It is Circular Quay. Most ferries start and end there. I am watching every gate.`)},C(440,null,`pixel`,`He has jumped on a bike. Pick it up for 300 metres before he turns the corner.`,150,{metres:300,chapter:`The chase`,half:x,fx:`riser`}),{at:560,kind:`story`,who:`pixel`,say:`He is fast. Like, annoyingly fast. Stay with him.`},{at:620,kind:`story`,who:`mack`,say:`[sighs] I am boxed in by a tour bus. A tour bus. You are on your own for a bit.`},C(700,null,`pixel`,`Bike lane through the park. Pick it up for 300 metres and keep him in sight.`,150,{metres:300,half:x}),{at:800,kind:`story`,spatial:`chatter`,say:`You weave through the crowd outside a cafe. Somebody says sorry. You say sorry back. Very Australian.`},{at:880,kind:`story`,who:`viv`,say:`Here is the double cross. The courier works for Crane, but he does not love Crane. Nobody does. Pixel, call him.`},{at:960,kind:`story`,who:`pixel`,say:`Done. I told him Crane forgot to pay him. He has stopped at the ferry wharf to make a very angry phone call.`},C(1040,null,`viv`,`He has put the briefcase down. Pick it up for 300 metres to the wharf.`,150,{metres:300,half:x,chapter:`The swap`,fx:`clock`}),{at:1180,kind:`story`,spatial:`helicopter`,say:`A news helicopter hangs over the harbour, filming the sunset. Try not to wave.`},{at:1210,kind:`story`,scene:`harbour`,say:`The wharf. Water slapping the pylons. A silver briefcase, next to a very cross courier, who is not looking.`},{at:1280,kind:`choice`,id:`swap`,who:`viv`,say:`[whispers] Two ways to do this. Swap the bags while he is on the phone, or have Pixel ring him again so he walks away?`,options:[{key:`A`,label:`Swap the bags`,flag:`swap`,say:p(`viv`,`[whispers] Smooth. Do not run. Then run.`)},{key:`B`,label:`Have Pixel ring him`,flag:`ring`,say:p(`pixel`,`[mischievously] Ringing. He has walked off to shout at someone. The briefcase is all yours.`)}],default:`A`,timeout:p(`viv`,`[whispers] Swap them. Now.`)},C(1340,60,`mack`,`Got it? Then go. Van is two streets up. Pick it up for 60 seconds.`,150,{half:x,fx:`horn`}),{at:1440,kind:`story`,who:`pixel`,say:`Watermark checks out. Nineteen oh two. Original ink. That is the real one. [excited] We have the real deed!`},{at:1530,kind:`steady`,seconds:180,scene:`street`,say:`Ease into a gentle pace while the crew celebrates. Breathe out long and slow.`,easyNudge:S},{at:1570,kind:`quiz`,who:`pixel`,say:`Pop quiz while we celebrate. The Sydney Opera House opened in which year?`,options:[{key:`A`,label:`1957`},{key:`B`,label:`1973`},{key:`C`,label:`1988`}],answer:`B`,right:p(`pixel`,`1973! The Queen opened it. Okay, I am impressed.`),wrong:p(`pixel`,`It was 1973. Building it took fourteen years. Like my code reviews.`)},{at:1650,kind:`story`,who:`crane`,say:`My lawyers have filed. The bulldozers start at dawn, deed or no deed. Unless the council says otherwise. And they meet at midnight.`},{at:1730,kind:`story`,who:`viv`,say:`Midnight at the Town Hall. Across the harbour. And Mack’s van has a flat tyre.`},{at:1790,kind:`finale`,say:`Episode three complete. The real deed is in your bag, and the last ferry leaves in forty minutes. To be continued.`,fx:`boom`}]},{id:`heist-ferry`,episode:4,previously:`Previously on The Night Job: the real deed is in your bag, Mack’s van has a flat, and the council votes at midnight.`,next:`Next time on The Night Job: Crane is out on bail, the harbour is lit up for Vivid, and his yacht is heading for the Heads.`,saga:`heist`,title:`The Last Ferry`,series:`thriller`,type:`surge`,minutes:35,difficulty:`Hard effort`,blurb:`Episode 4. A deed, a deadline and the whole city between you and the Town Hall.`,loop:p(`viv`,`One more loop. This city is yours now.`),early:p(`viv`,`That will do. Pixel has a scan of the deed on its way to the council. You got us close enough.`),beats:[{at:3,kind:`recover`,seconds:300,chapter:`Forty minutes`,scene:`harbour`,say:`Eleven twenty at night. The deed is zipped in your bag. The last ferry leaves soon. Warm up easy.`},{at:50,kind:`story`,spatial:`chatter`,say:`On the wharf, a hen’s party is singing. Badly. Nobody looks at you twice.`},{at:110,kind:`story`,who:`viv`,say:`Plan. Ferry to Circular Quay, then on foot to the Town Hall. Pixel clears the lights. I stall the council. You run.`},{at:210,kind:`story`,who:`pixel`,say:`Bad news. Crane has people at every taxi rank. Good news. Nobody looks at runners. You are invisible.`},C(300,60,`viv`,`Ferry is pulling out. Pick it up for 60 seconds and make the jump.`,120,{chapter:`The ferry`,half:x,fx:`horn`}),{at:390,kind:`story`,say:`The ferry chugs across black water. The Opera House glows. Your heart slowly comes back down.`},{at:470,kind:`story`,who:`reg`,say:`Reg here. I am at the Town Hall. Twenty eight years of night shifts and I have finally got something to say to a council.`},C(560,60,`pixel`,`Two of Crane’s people at the Quay. Pick it up for 60 seconds off the wharf and into the crowd.`,120,{chapter:`Circular Quay`,half:x,scene:`street`,fx:`footsteps`}),{at:650,kind:`story`,spatial:`car`,say:`Taxis beep. A bus pulls out right in front of you. You are round it before the driver blinks.`},C(710,60,`pixel`,`They are following. Up George Street. Pick it up for 60 seconds. I will turn the lights red behind you.`,120,{half:x}),{at:800,kind:`story`,who:`pixel`,say:`[laughs] Six red lights in a row. They are very cross. Very stopped.`},{at:870,kind:`steady`,seconds:240,say:`You have lost them. Hold an easy pace through the back lanes. Stay invisible.`,easyNudge:S},{at:930,kind:`puzzle`,who:`pixel`,say:`The Town Hall back door wants a code. Viv says it is the year the Harbour Bridge opened. Which is it?`,options:[{key:`A`,label:`1923`},{key:`B`,label:`1932`},{key:`C`,label:`1942`}],answer:`B`,right:p(`pixel`,`1932. Door is open. You are very good at this.`),wrong:p(`pixel`,`It opened in 1932. Typing it in now. Door is open.`)},{at:1e3,kind:`story`,who:`viv`,say:`I am in the chamber. Crane is here too. He is smiling. He thinks you are stuck at the Quay.`},{at:1060,kind:`story`,fx:`clock`,say:`High above, the Town Hall clock chimes the quarter hour. Fifteen minutes to midnight.`},{at:1120,kind:`story`,who:`crane`,say:`Councillors, there is no deed. There never was. Let us vote, and let us all go home rich.`},C(1180,60,`viv`,`They are about to vote. Pick it up for 60 seconds. Town Hall steps, now.`,120,{chapter:`The Town Hall`,half:x,scene:`tower`,fx:`clock`}),{at:1290,kind:`choice`,id:`steps`,who:`mack`,say:`Crane’s security is on the front steps. Walk straight past them like you own the place, or take the loading bay round the back?`,options:[{key:`A`,label:`Walk past them`,flag:`bold`,say:p(`viv`,`[mischievously] Confidence is the best disguise. Chin up.`)},{key:`B`,label:`The loading bay`,flag:`bay`,say:p(`mack`,`Loading bay. I will hold the door.`)}],default:`B`,timeout:p(`mack`,`Loading bay. Go.`)},C(1330,60,`mack`,`Back entrance, through the loading bay. Pick it up for 60 seconds.`,150,{unless:`bold`,half:x,fx:`alarm`}),C(1331,60,`viv`,`Chin up, straight past the guards and up the steps. Pick it up for 60 seconds.`,150,{if:`bold`,half:x,fx:`heartbeat`}),{at:1440,kind:`story`,say:`The chamber doors swing open. Every head turns. You hold up an old envelope. Crane stops smiling.`,fx:`impact`},{at:1520,kind:`story`,who:`reg`,say:`That is the real deed. I saw it in his safe for twenty eight years. And I saw him make the copy.`},{at:1600,kind:`story`,spatial:`firetruck`,say:`Sirens outside. Blue lights flicker through the tall windows. The fraud squad has arrived.`},{at:1610,kind:`story`,who:`crane`,say:`This is outrageous. Get your hands off me. Do you know who I am?`,fx:`siren`},{at:1700,kind:`story`,who:`viv`,say:`The fraud squad knows exactly who you are, Lachlan. Pixel sent them everything an hour ago.`},{at:1790,kind:`steady`,seconds:180,scene:`harbour`,say:`Cool down now with a gentle jog or a walk. The city is quiet, and the harbour is still.`,chapter:`Morning`},{at:1900,kind:`story`,who:`mack`,say:`Coffee. Finally. And for the record, you were not bad. For someone without a van.`},{at:2e3,kind:`story`,who:`pixel`,fx:`cheer`,say:`The Harbourside Pool opens at six. First swim is on Reg. He has been waiting twenty eight years.`},{at:2080,kind:`finale`,who:`viv`,say:`Episode four complete. The pool stays and Crane goes. Or does he? [laughs] I will be in touch. To be continued.`}]},{id:`heist-vivid`,episode:5,previously:`Previously on The Night Job: a race to the Town Hall, the real deed held high, and Crane led away by the fraud squad.`,saga:`heist`,title:`Lights Out`,series:`thriller`,type:`surge`,minutes:35,difficulty:`Hard effort`,blurb:`Episode 5, the finale. Crane is out on bail, the harbour is lit up for Vivid, and his yacht is making a run for the Heads.`,loop:p(`viv`,`Loop closed. You know this city better than Crane ever will.`),early:p(`viv`,`That will do, darling. The water police have it from here. You got us there.`),beats:[{at:3,kind:`recover`,seconds:300,chapter:`Vivid`,scene:`vivid`,say:`Six weeks later. Winter in Sydney, and the whole harbour glows. Vivid lights ripple across the Opera House sails. Warm up easy.`},{at:50,kind:`story`,spatial:`chatter`,say:`Crowds shuffle along the Quay, faces lit pink, then green, then gold. A toddler goes past in light up shoes.`},{at:110,kind:`story`,who:`viv`,say:`Bad news, darling. Crane’s lawyers got him out on bail. And he has not stopped smiling.`},{at:170,kind:`story`,who:`pixel`,say:`Worse news. The Regal just fuelled up at Rushcutters Bay. Crane is sailing out through the Heads tonight, with a laptop full of every dodgy deal he ever did.`},{at:240,kind:`story`,who:`mack`,say:`I have got a boat. Sort of. My cousin’s tinnie. Meet me at the Man O’War Steps, by the Opera House.`},C(300,45,`viv`,`Crane’s people are watching the Quay. Pick it up for 45 seconds and weave through the crowd to the steps.`,130,{chapter:`The Quay`,half:x,fx:`footsteps`}),{at:400,kind:`story`,fx:`whoosh`,say:`The sails flash bright white. Ten thousand people go ooh. In the glare, you slip straight past two of Crane’s security guards.`},{at:460,kind:`story`,who:`pixel`,say:`[mischievously] I can borrow one Vivid projector for ninety seconds. Every boat on the harbour will see whatever I put on those sails.`},{at:520,kind:`choice`,id:`sails`,who:`viv`,say:`What goes up on the sails? Crane’s face with a wanted sign, or a message telling the water police exactly where the Regal is?`,options:[{key:`A`,label:`Crane’s face`,flag:`face`,say:p(`pixel`,`[laughs] His worst photo. The one from the gala, with spinach in his teeth.`)},{key:`B`,label:`A message to the police`,flag:`police`,say:p(`viv`,`Sensible, and devastating. Pixel, send it.`)}],default:`B`,timeout:p(`viv`,`Message to the police. Pixel, go.`)},{at:590,kind:`story`,if:`face`,fx:`cheer`,say:`Crane’s face fills the sails, ten storeys tall, spinach and all. The whole Quay laughs at once.`},{at:591,kind:`story`,unless:`face`,fx:`cheer`,say:`Giant letters glide across the sails. Water police. Yacht Regal. Heading for the Heads. The crowd cheers like it is part of the show.`},{at:650,kind:`story`,spatial:`boat`,fx:`splash`,say:`Mack’s tinnie roars away from the steps, spray in your face. Fort Denison slides past in the dark.`},{at:710,kind:`story`,who:`mack`,say:`I cannot catch a yacht in this thing. But I can drop you at Rose Bay. From there, you run.`},{at:770,kind:`steady`,seconds:200,scene:`street`,say:`Rose Bay. Sand, then footpath. Hold an easy pace along the water while the plan comes together.`,easyNudge:S},{at:840,kind:`quiz`,who:`reg`,say:`Reg here, while you jog. Everyone calls it Sydney Harbour. But what is its official name?`,options:[{key:`A`,label:`Port Jackson`},{key:`B`,label:`Botany Bay`},{key:`C`,label:`Port Phillip`}],answer:`A`,right:p(`reg`,`Port Jackson. Twenty eight years of night shifts and I still know my harbour.`),wrong:p(`reg`,`It is Port Jackson. Twenty eight years of night shifts and I still know my harbour.`)},{at:910,kind:`story`,who:`pixel`,fx:`beeps`,say:`The Regal is past Bradleys Head and speeding up. Water police are four minutes behind. They need a light on her at the Heads.`},{at:970,kind:`story`,who:`viv`,say:`Hornby Lighthouse, on South Head. Red and white stripes. Get up there, and Pixel can patch you into the signal lamp.`},C(1030,60,`viv`,`Up the hill toward Watsons Bay. Pick it up for 60 seconds!`,150,{chapter:`South Head`,half:x,fx:`screech`}),{at:1150,kind:`story`,spatial:`car`,say:`A taxi slows beside you and the driver leans out. Mate, you are the runner from the news! Go on, go!`},{at:1210,kind:`story`,who:`crane`,fx:`horn`,say:`[sarcastic] Enjoy the view, runner. By sunrise I will be somewhere with no extradition and much better coffee.`},{at:1270,kind:`puzzle`,who:`pixel`,say:`The lamp needs a Morse signal. S O S is three short flashes, three long, then three short. How many flashes is that?`,options:[{key:`A`,label:`6`},{key:`B`,label:`9`},{key:`C`,label:`12`}],answer:`B`,right:p(`pixel`,`Nine flashes. Short, long, short. Lamp is ready.`),wrong:p(`pixel`,`It is 9. Three short, three long, three short. Lamp is ready.`)},C(1340,60,`pixel`,`The cliff path to the lighthouse. Pick it up for 60 seconds. The Regal is almost at the Heads!`,150,{chapter:`The lighthouse`,scene:`harbour`,half:x,fx:`riser`}),{at:1460,kind:`story`,fx:`impact`,say:`You reach the striped tower, gasping. Pixel throws the switch. A beam of light swings out over the black water and lands right on the Regal.`},{at:1520,kind:`story`,spatial:`boat`,fx:`siren`,say:`Engines roar out of the dark. Blue lights. Three water police boats swing in around the Regal. One, two, three.`},{at:1580,kind:`story`,who:`crane`,say:`This is outrageous. I have a dinner booking in Fiji! [sighs] Fine. Fine. Somebody get me a towel.`},{at:1640,kind:`story`,who:`viv`,say:`Laptop recovered. Every dodgy deal, every forged signature. The fraud squad says thank you. So do I.`},{at:1700,kind:`steady`,seconds:180,chapter:`Sunrise`,say:`Dawn creeps up over the ocean. The lighthouse goes pale against a pink sky. Cool down now with a gentle jog or a walk.`},{at:1800,kind:`story`,who:`mack`,say:`My cousin wants his tinnie back. I told him it is a hero boat now. He is very confused.`},{at:1870,kind:`story`,who:`reg`,fx:`cheer`,say:`The Harbourside Pool’s winter swim is at seven. Bring your togs. Nobody is in charge of the cold.`},{at:1940,kind:`finale`,who:`viv`,say:`The Night Job is complete. Crane is caught, the pool is safe, and the harbour is ours. [laughs] Same time next year? I mean it this time.`}]},...d,...e.flatMap(e=>e.EPISODES)],w={signal:f,...Object.fromEntries(e.map(e=>[e.SAGA.id,e.CHAIN])),ember:[`ember-smoke`,`ember-wind`,`ember-tower`,`ember-dawn`,`ember-flood`],heist:[`heist-recruit`,`heist-gala`,`heist-cross`,`heist-ferry`,`heist-vivid`]},T=(e,t)=>({who:e,text:t}),oe=T(`tex`,`Look at that pace! Bonus points in the bank. Ease right back now.`),se=T(`tex`,`Points on the board all the same. Ease right back now.`),ce=T(`milly`,`Halfway! Keep it going!`),E=T(`tex`,`Ten seconds! Give it everything!`),D=T(`tex`,`Easy does it. Save the legs for the sprints, that is where the money is.`),O=(e,t,n,r,i,a={})=>({at:e,kind:`surge`,seconds:t,who:`tex`,say:n,success:oe,okay:se,recover:i,points:r,half:ce,ten:E,clock:!0,...a}),k=(e,t,n,r,i,a,o,s=1e3,c={})=>({at:e,kind:`quiz`,who:t,say:n,points:s,wait:22,options:r.map((e,t)=>({key:`ABC`[t],label:e})),answer:i,right:T(t,a),wrong:T(t,o),...c}),A=(e,t,n,r,i)=>k(e,`milly`,`${t}. Real or rubbish?`,[`Real`,`Rubbish`],n?`A`:`B`,r,i,1500),j=e=>({at:e,kind:`finale`,say:({score:e,right:t,total:n})=>T(`tex`,`That is the show! You got ${t} of ${n} right and finished on ${e.toLocaleString(`en-AU`)} points. Same time next week?`)}),M={saga:`quiz`,series:`gameshow`,type:`surge`,scored:!0,brisk:!0,host:`tex`,climbPoints:50,hillLines:[`Hill bonus! Every metre up is money in the bank.`,`You are climbing, and so is your score.`,`Uphill points! The judges love a hill.`]},N={id:`quiz`,title:`Run Your Mouth`,blurb:`The trivia game show you play on your feet. Quick answers score big, sprints and hills pay bonus points.`,narrator:`announcer`,score:`quiz`},P=e=>[{at:3,kind:`recover`,seconds:150,chapter:`Welcome`,who:`announcer`,fx:`cheer`,say:`From the Foothold studios, it is the trivia show you play on your feet. It is Run Your Mouth! ${e}. And here is your host, Tex Tilley!`},{at:14,kind:`story`,who:`tex`,fx:`hostin`,say:`[excited] Thank you, thank you! What a crowd! Here is how it works. Answer out loud or tap, and quicker answers score more.`},{at:26,kind:`story`,who:`tex`,say:`Sprints pay bonus points, and so does every hill you climb. Let us play!`}],F=(e,t=`tex`)=>({at:e,kind:`story`,who:t,say:({score:e,right:n,total:r})=>T(t,r?`Scoreboard check! ${n} of ${r} right, and you are on ${e.toLocaleString(`en-AU`)} points.`:`Scoreboard check! You are on ${e.toLocaleString(`en-AU`)} points, and the questions are only getting started.`)}),I=(e,t,n,r,i,a)=>k(e,`tex`,t,n,r,i,a,500,{wait:15}),L=(e,t,n,r={})=>({at:e,kind:`story`,who:t,say:n,...r}),R=[{...M,id:`quiz-1`,episode:1,title:`The Warm Up`,minutes:10,difficulty:`Gentle`,blurb:`Show 1. Marathons, emus, a place called Nowhere Else and a lightning round.`,loop:T(`tex`,`You closed a loop! The hexes are yours, and so is my respect.`),early:T(`tex`,`Leaving early? No worries. Your points are safe and the trophy cabinet awaits.`),beats:[...P(`Show one, the warm up`),L(75,`milly`,`Hi everyone! I am Milly, and I am in charge of the buzzer. I have already pressed it twice by accident.`),k(110,`tex`,`First question, for a thousand points. How long is a marathon?`,[`40 kilometres`,`42.195 kilometres`,`45 kilometres`],`B`,`Correct! 42.195 kilometres, every last metre of it.`,`Ooh, no. It is 42.195 kilometres. That last 195 metres is the cheeky bit.`),L(170,`tex`,`Legend says the very first marathon runner carried news all the way to Athens. Then he needed a very long lie down. Pace yourself.`),k(210,`tex`,`Next one. Which bird stands beside the kangaroo on Australia’s coat of arms?`,[`The emu`,`The kookaburra`,`The cockatoo`],`A`,`The emu! Neither of them can walk backwards, so they only go forward. Like you.`,`It is the emu. The kookaburra is laughing about that one.`),L(260,`milly`,`Tex, an emu can run at about 50 kilometres an hour. Should we tell our player?`),L(290,`tex`,`Milly, let us not crush anyone’s dreams on show one.`),F(320),O(350,30,`Ad break! Sprint for 30 seconds. The faster you go, the bigger the bonus.`,1e3,120,{chapter:`Ad break`}),L(420,`tex`,`And we are back. The sponsors were thrilled with that. We do not have sponsors, but if we did.`),L(460,`milly`,`It is time for Real or Rubbish! I say a place name, you tell me if it is a real place in Australia.`,{chapter:`Real or Rubbish`,fx:`question`}),A(495,`Nowhere Else, Tasmania`,!0,`Real! Nowhere Else is a real place in Tasmania. You cannot make this stuff up.`,`It is real! Nowhere Else is in Tasmania. Somebody had a sense of humour.`),A(555,`Snoozebottom, Victoria`,!1,`Rubbish! I made that one up. It sounds lovely though.`,`Rubbish! There is no Snoozebottom. I made it up after a long nap.`),A(615,`Come By Chance, New South Wales`,!0,`Real! Come By Chance is in western New South Wales.`,`It is real! Come By Chance is in western New South Wales.`),L(670,`milly`,`I would love to live in Nowhere Else. Imagine giving people directions.`),L(705,`tex`,`Lightning round! Three quick ones, fifteen seconds each, five hundred points a pop. Go!`,{chapter:`Lightning round`,fx:`clock`}),I(735,`Which planet is known as the red planet?`,[`Mars`,`Venus`,`Jupiter`],`A`,`Mars!`,`It is Mars. Next!`),I(770,`The biggest ocean on Earth?`,[`The Atlantic`,`The Pacific`,`The Indian`],`B`,`The Pacific!`,`It is the Pacific. Last one!`),I(805,`The capital of Western Australia?`,[`Perth`,`Broome`,`Fremantle`],`A`,`Perth! What a round.`,`It is Perth. Nice try, what a round.`),O(850,45,`Ad break! 45 seconds this time. Leave nothing in the tank.`,1500,150,{chapter:`Ad break`}),L(930,`milly`,`Did anyone else feel the studio shake? That was you. Brilliant.`),F(980),L(1015,`tex`,`Welcome back. It is the double points round, where the questions are worth twice as much.`,{chapter:`Double points`,fx:`hostin`}),k(1050,`tex`,`For two thousand points. At the Sydney 2000 Olympics, Cathy Freeman won gold in which event?`,[`The 100 metres`,`The 400 metres`,`The marathon`],`B`,`The 400 metres! The whole country stood up for that one.`,`It was the 400 metres. One of the great nights in Australian sport.`,2e3),L(1110,`milly`,`I watched that race on telly. I mostly remember the hot chips. And the yelling. Lots of yelling.`),k(1145,`tex`,`The final question, for three thousand points. How far is a parkrun?`,[`3 kilometres`,`5 kilometres`,`10 kilometres`],`B`,`5 kilometres! Every Saturday morning. See you there.`,`It is 5 kilometres, every Saturday morning. You will smash it next time.`,3e3,{chapter:`The final question`}),L(1200,`tex`,`While the judges count it up, ease into a gentle jog. You have earned it.`),L(1240,`milly`,`The judges are me. I am counting on my fingers. Give me a sec.`),j(1275)]},{...M,id:`quiz-2`,episode:2,title:`Snags and Servos`,minutes:10,difficulty:`Steady effort`,blurb:`Show 2. Pavlova, City2Surf, a town called Wonglepong and a lightning round.`,loop:T(`tex`,`Loop closed! That is ground and points. A great combination.`),early:T(`tex`,`Off already? Fair enough. Your points are locked in.`),beats:[...P(`Show two, snags and servos`),L(75,`milly`,`Welcome back! I have been practising the buzzer all week. My neighbours are not happy.`),k(110,`tex`,`For a thousand points. The pavlova is named after a famous what?`,[`Ballerina`,`Racehorse`,`Prime minister`],`A`,`A ballerina! Anna Pavlova. Light, fluffy and full of energy, like you right now.`,`It was a ballerina, Anna Pavlova. Not a racehorse, though that would be a great story.`),L(170,`milly`,`Tex, I brought a pav for the studio audience. It is mostly cream. I regret nothing.`),k(210,`tex`,`Sydney’s City2Surf finishes at which beach?`,[`Manly`,`Bondi`,`Coogee`],`B`,`Bondi! Fourteen kilometres from the city to the surf.`,`It is Bondi. Fourteen kilometres from the city to the surf, and one big hill.`),L(265,`tex`,`That big hill on the City2Surf is called Heartbreak Hill. If you find a hill today, the points are yours.`),F(300),O(330,45,`Ad break! Sprint for 45 seconds. The quicker you go, the more it pays.`,1500,150,{chapter:`Ad break`}),L(430,`tex`,`Lovely running. Milly, what is next?`),L(460,`milly`,`Real or Rubbish time! Is it a real Australian place, or did I make it up?`,{chapter:`Real or Rubbish`,fx:`question`}),A(495,`Woolloomooloo, New South Wales`,!0,`Real! Woolloomooloo is right next to the Sydney CBD. Eight O’s, if you are counting.`,`Real! Woolloomooloo is right next to the Sydney CBD. Eight O’s, if you are counting.`),A(555,`Thongbottom Creek, Queensland`,!1,`Rubbish! I invented it on the way to work.`,`Rubbish! There is no Thongbottom Creek. Yet.`),A(615,`Wonglepong, Queensland`,!0,`Real! Wonglepong is in the Scenic Rim. What a name.`,`It is real! Wonglepong is in Queensland’s Scenic Rim. What a name.`),L(670,`milly`,`Wonglepong sounds like a ping pong move. I am going to start using it.`),L(705,`tex`,`Lightning round! Fifteen seconds each, five hundred points. Here we go.`,{chapter:`Lightning round`,fx:`clock`}),I(735,`Which Australian animal sleeps up to twenty hours a day?`,[`The koala`,`The wombat`,`The echidna`],`A`,`The koala! Living the dream.`,`It is the koala. Living the dream. Next!`),I(770,`The MCG is in which city?`,[`Sydney`,`Melbourne`,`Adelaide`],`B`,`Melbourne!`,`It is Melbourne. Last one!`),I(805,`How many hearts does an octopus have?`,[`One`,`Two`,`Three`],`C`,`Three! Very big hearted.`,`It is three. Very big hearted.`),O(850,30,`Ad break! A short sharp 30 seconds. Make it count.`,1e3,150,{chapter:`Ad break`}),L(920,`tex`,`Puffing? Good puffing. That is the sound of points.`),F(955),L(1010,`tex`,`We are back with double points. Hold on to your hats.`,{chapter:`Double points`,fx:`hostin`}),k(1045,`tex`,`For two thousand points. Which Australian bird is famous for its laugh?`,[`The galah`,`The kookaburra`,`The magpie`],`B`,`The kookaburra! And it is laughing with you, not at you.`,`It is the kookaburra. It is laughing with you, I promise.`,2e3,{spatial:`kookaburra`}),L(1105,`milly`,`I can do a kookaburra impression. No, Tex says I cannot. Not on air.`),k(1140,`tex`,`The final question, for three thousand points. The Ashes is a contest in which sport?`,[`Rugby`,`Tennis`,`Cricket`],`C`,`Cricket! Australia versus England, and nobody ever gets over it.`,`It is cricket. Australia versus England, every couple of years.`,3e3,{chapter:`The final question`}),L(1200,`tex`,`Ease into a gentle jog while we tally it up. Breathe it in.`),L(1240,`milly`,`Drumroll please. That is me. I am the drumroll.`,{fx:`timpani`}),j(1275)]},{...M,id:`quiz-3`,episode:3,title:`The Grand Final`,minutes:12,difficulty:`Hard effort`,blurb:`Show 3. Uluru, the Melbourne Cup, the fastest marathon ever and a lightning round.`,loop:T(`tex`,`A loop in the grand final! The crowd goes wild.`),early:T(`tex`,`Taking an early mark? Your points are safe. Champions rest too.`),beats:[...P(`The grand final`),L(75,`milly`,`It is the grand final! I have a new outfit. It has sequins. You cannot see it, but trust me.`),k(110,`tex`,`For a thousand points. Uluru is in which part of Australia?`,[`Western Australia`,`South Australia`,`The Northern Territory`],`C`,`The Northern Territory! Right in the red centre.`,`It is the Northern Territory, right in the red centre.`),k(175,`milly`,`My turn! True or false. The platypus lays eggs.`,[`True`,`False`],`A`,`True! A mammal that lays eggs. Nature was having a fun day.`,`True, believe it or not! A mammal that lays eggs. Nature was having a fun day.`),L(235,`tex`,`Grand final rules: sprints pay big, and hills pay bigger. If you see a hill, go and say hello.`),F(270),O(300,45,`Ad break! Sprint for 45 seconds, and do not hold back.`,1500,60,{chapter:`Ad break`}),L(380,`milly`,`The sponsors want another one, Tex.`),O(430,45,`And another! The sponsors want more. 45 seconds.`,1500,150),L(510,`tex`,`The judges are calling that one a personal best for enthusiasm.`),L(560,`tex`,`Two big pushes. The crowd is on its feet. Well, Milly is.`),L(595,`milly`,`Grand final Real or Rubbish! Three place names. Which are real?`,{chapter:`Real or Rubbish`,fx:`question`}),A(630,`Banana, Queensland`,!0,`Real! Banana is a town in central Queensland.`,`It is real! Banana is a town in central Queensland. No bananas required.`),A(690,`Vegemite Vale, Victoria`,!1,`Rubbish! Sadly, no such place. Somebody should build it.`,`Rubbish! No Vegemite Vale, sadly. Somebody should build it.`),A(750,`Dingo, Queensland`,!0,`Real! Dingo is a small town in central Queensland.`,`It is real! Dingo is a small town in central Queensland.`),L(805,`tex`,`Lightning round, grand final edition! Fifteen seconds, five hundred points each.`,{chapter:`Lightning round`,fx:`clock`}),I(835,`The tallest mountain on the Australian mainland?`,[`Mount Kosciuszko`,`Mount Bogong`,`Uluru`],`A`,`Mount Kosciuszko!`,`It is Mount Kosciuszko. Next!`),I(870,`Australia’s longest river?`,[`The Darling`,`The Murray`,`The Yarra`],`B`,`The Murray!`,`It is the Murray. Last one!`),I(905,`About how long is a half marathon?`,[`15 kilometres`,`21.1 kilometres`,`25 kilometres`],`B`,`21.1 kilometres! Spot on.`,`It is 21.1 kilometres. Half of 42.195, near enough.`),O(950,60,`Last ad break of the season! 60 seconds, everything you have got.`,2500,180,{chapter:`Ad break`}),L(1050,`milly`,`That was the biggest sprint of the season. I am out of breath and I was sitting down.`),F(1090),L(1130,`tex`,`Double points, grand final edition. This is where champions are made.`,{chapter:`Double points`,fx:`hostin`}),k(1205,`tex`,`For two thousand points. The Melbourne Cup is run on which day?`,[`First Tuesday in November`,`Boxing Day`,`First Saturday in March`],`A`,`The first Tuesday in November! The race that stops a nation.`,`It is the first Tuesday in November. The race that stops a nation.`,2e3),L(1265,`milly`,`I once put five dollars on a horse called Lunchbox. It is still running, I think.`),k(1300,`tex`,`The final question of the season, for five thousand points. Who ran the first marathon under two hours, in 2019?`,[`Eliud Kipchoge`,`Mo Farah`,`Usain Bolt`],`A`,`Eliud Kipchoge! One hour, 59 minutes and 40 seconds. Absolute legend.`,`It was Eliud Kipchoge, in one hour 59 minutes and 40 seconds. Usain would have needed a lie down.`,5e3,{chapter:`The final question`}),{at:1360,kind:`steady`,seconds:60,who:`tex`,say:`While the judges tally it up, ease into a gentle jog. You have earned it.`,easyNudge:D},L(1395,`milly`,`It is official, I have run out of fingers. Tex has lent me his. And next week, season two hits the road!`,{fx:`timpani`}),j(1430)]},{...M,id:`quiz-4`,episode:4,title:`The Road Trip`,minutes:12,difficulty:`Steady effort`,blurb:`Show 4, season two. An outside broadcast, the Big Banana, a place called Humpty Doo and a buzzer beater sprint.`,loop:T(`tex`,`A loop on the road trip! Somebody put that on a postcard.`),early:T(`tex`,`Pulling into the servo early? Your points are safe. See you down the road.`),beats:[...P(`Season two, on the road`),L(70,`milly`,`[excited] We are on the road! The studio is a caravan now. Tex has packed fourteen hats.`,{fx:`horn`}),k(105,`tex`,`For a thousand points. The Big Banana is a famous roadside giant in which town?`,[`Coffs Harbour`,`Byron Bay`,`Cairns`],`A`,`Coffs Harbour! Big, yellow, and very photogenic.`,`It is Coffs Harbour. Big, yellow, and very photogenic.`),k(170,`milly`,`True or false. A group of kangaroos is called a mob.`,[`True`,`False`],`A`,`True! A mob. They do not wear sunglasses, sadly.`,`True, believe it or not! A mob of kangaroos. No sunglasses, sadly.`),L(225,`tex`,`Road trip rules: every hill is a bonus, and every sprint is a ticket out of the back seat.`),F(260),O(290,45,`Ad break! Overtaking lane ahead. Sprint for 45 seconds!`,1500,70,{chapter:`Ad break`,fx:`riser`}),L(370,`milly`,`That was so fast the caravan wobbled. I spilled my iced coffee.`),L(410,`milly`,`Road trip Real or Rubbish! Three place names from the map. Which are real?`,{chapter:`Real or Rubbish`,fx:`question`}),A(440,`Humpty Doo, Northern Territory`,!0,`Real! Humpty Doo is a town near Darwin.`,`It is real! Humpty Doo is a town just outside Darwin.`),A(500,`Snag Junction, South Australia`,!1,`Rubbish! No such place. Snags are for the barbie.`,`Rubbish! There is no Snag Junction. Snags are for the barbie.`),A(560,`Bobs Farm, New South Wales`,!0,`Real! Bobs Farm is near Port Stephens. Bob was not available for comment.`,`It is real! Bobs Farm is near Port Stephens. Bob was not available for comment.`),L(615,`tex`,`Now, a new round for season two. The Buzzer Beater! Beat the buzzer and the points double.`,{chapter:`Buzzer Beater`,fx:`clock`}),O(650,45,`Buzzer Beater! The clock is ticking. 45 seconds, flat out!`,2e3,150,{fx:`clock`}),L(740,`tex`,`[excited] Buzzer beaten! The judges are standing on their chairs.`,{fx:`cheer`}),L(785,`tex`,`Lightning round, road trip edition! Fifteen seconds, five hundred points each.`,{chapter:`Lightning round`,fx:`clock`}),I(815,`The capital of Tasmania?`,[`Launceston`,`Hobart`,`Devonport`],`B`,`Hobart!`,`It is Hobart. Next!`),I(850,`How many states does Australia have?`,[`Five`,`Six`,`Seven`],`B`,`Six!`,`It is six, plus two territories. Next!`),I(885,`Which ocean lies to the west of Australia?`,[`The Pacific`,`The Indian`,`The Southern`],`B`,`The Indian Ocean!`,`It is the Indian Ocean. Last one done!`),O(930,60,`Last ad break of the trip! 60 seconds to the finish line.`,2500,160,{chapter:`Ad break`}),F(1030),L(1065,`tex`,`Double points, road trip edition.`,{chapter:`Double points`,fx:`hostin`}),k(1095,`tex`,`For two thousand points. The Great Barrier Reef lies off the coast of which state?`,[`Queensland`,`Western Australia`,`New South Wales`],`A`,`Queensland! The biggest reef on the planet.`,`It is Queensland. The biggest reef on the planet.`,2e3),k(1160,`tex`,`The final question of the trip, for five thousand points. The famous Dog on the Tuckerbox sits near which town?`,[`Gundagai`,`Wagga Wagga`,`Dubbo`],`A`,`Gundagai! About eight kilometres out of town, on the old highway.`,`It is Gundagai. A very good dog, sitting on a very good tuckerbox.`,5e3,{chapter:`The final question`}),{at:1230,kind:`steady`,seconds:60,who:`tex`,say:`While the judges tally it up, ease into a gentle jog. Next stop, the champions.`,easyNudge:D},L(1265,`milly`,`Next week, it is Champion of Champions. I am already nervous and I am not even playing.`,{fx:`timpani`}),j(1300)]},{...M,id:`quiz-5`,episode:5,title:`Champion of Champions`,minutes:14,difficulty:`Hard effort`,blurb:`Show 5, the season two final. The Moon, a wombat fact you will never forget, a town called Useless Loop and a winner takes all question.`,loop:T(`tex`,`A loop in the final! That is champion behaviour.`),early:T(`tex`,`Stopping early is fine. Champions rest. Your points are safe.`),beats:[...P(`Champion of Champions`),L(70,`milly`,`[excited] Confetti cannons are loaded. Tex has a gold jacket. I have a gold everything.`,{fx:`cheer`}),k(105,`tex`,`For a thousand points. Who was the first person to walk on the Moon?`,[`Buzz Aldrin`,`Neil Armstrong`,`Yuri Gagarin`],`B`,`Neil Armstrong! One small step, and one big thousand points.`,`It was Neil Armstrong. Buzz followed him down the ladder.`),k(170,`milly`,`True or false. Wombats do cube shaped poo.`,[`True`,`False`],`A`,`True! Little cubes. Nature is a genius.`,`True, believe it or not! Little cubes, so they do not roll away.`),L(225,`tex`,`Champion rules: everything pays double the nerves. Sprints pay big. Hills pay bigger.`),F(260),O(290,45,`Ad break! The champions sprint for 45 seconds. Go!`,1500,70,{chapter:`Ad break`}),L(370,`milly`,`That is the fastest anyone has run past our camera all season.`),L(410,`milly`,`Champion Real or Rubbish! Three place names. Which are real?`,{chapter:`Real or Rubbish`,fx:`question`}),A(440,`Useless Loop, Western Australia`,!0,`Real! Useless Loop is in Shark Bay. Not useless at all.`,`It is real! Useless Loop is up in Shark Bay. Not useless at all.`),A(500,`Doo Town, Tasmania`,!0,`Real! In Doo Town, the houses have names like Doo Drop Inn.`,`It is real! In Doo Town, the houses have names like Doo Drop Inn.`),A(560,`Lollygag Lagoon, New South Wales`,!1,`Rubbish! Lovely name, though. Somebody should lollygag there.`,`Rubbish! There is no Lollygag Lagoon. Lovely name, though.`),L(615,`tex`,`The Buzzer Beater, champion edition. Beat the buzzer and the points triple!`,{chapter:`Buzzer Beater`,fx:`clock`}),O(650,60,`Buzzer Beater! 60 seconds, flat out, and triple points!`,3e3,160,{fx:`clock`}),L(750,`milly`,`[excited] Buzzer beaten! The confetti cannons went off by accident. There is gold everywhere.`,{fx:`cheer`}),L(800,`tex`,`Lightning round, champion edition! Fifteen seconds, five hundred points each.`,{chapter:`Lightning round`,fx:`clock`}),I(830,`The capital of the Northern Territory?`,[`Alice Springs`,`Darwin`,`Katherine`],`B`,`Darwin!`,`It is Darwin. Next!`),I(865,`How many players does a netball team have on court?`,[`Five`,`Seven`,`Eleven`],`B`,`Seven!`,`It is seven. Next!`),I(900,`Which planet is closest to the Sun?`,[`Venus`,`Mercury`,`Mars`],`B`,`Mercury!`,`It is Mercury. Last one done!`),O(945,60,`The last ad break of season two! 60 seconds, everything you have got.`,3e3,170,{chapter:`Ad break`,fx:`riser`}),L(1045,`milly`,`Tex is crying. He says it is the confetti. It is not the confetti.`),F(1085),L(1120,`tex`,`Double points, champion edition.`,{chapter:`Double points`,fx:`hostin`}),k(1150,`tex`,`For two thousand points. Which Australian swimmer was nicknamed the Thorpedo?`,[`Ian Thorpe`,`Grant Hackett`,`Kieren Perkins`],`A`,`Ian Thorpe! The Thorpedo. Fast in the pool, and that name is perfect.`,`It was Ian Thorpe. The Thorpedo. A perfect name.`,2e3),L(1210,`tex`,`And now, winner takes all. The champion question.`,{chapter:`The champion question`,fx:`heartbeat`}),k(1250,`tex`,`For ten thousand points. In a full marathon, how far do you run?`,[`40 kilometres`,`42.195 kilometres`,`45 kilometres`],`B`,`42.195 kilometres! Of course a runner knows that. Champion!`,`It is 42.195 kilometres. You are a runner, you will be doing it next.`,1e4),{at:1320,kind:`steady`,seconds:60,who:`tex`,say:`While the judges count every point, ease into a gentle jog. What a season.`,easyNudge:D},L(1355,`milly`,`The judges have run out of calculators. Tex has lent them his phone.`,{fx:`timpani`}),{at:1390,kind:`finale`,say:({score:e,right:t,total:n})=>T(`tex`,`That is the season! You got ${t} of ${n} right and finished on ${e.toLocaleString(`en-AU`)} points. You are a champion of champions.`)}]}],z=[`quiz-1`,`quiz-2`,`quiz-3`,`quiz-4`,`quiz-5`],B=`You lost them. Brilliant running. Ease right back now.`,V=`You got away anyway. Nice work. Ease right back now.`,H=`Made it. Brilliant running. Ease right back now.`,U=`You got there anyway. Nice work. Ease right back now.`,W=`Halfway. Keep it up.`,G=`Easy does it. Scouts move quietly, so ease back a touch.`,K=`Cool down now with a gentle jog or a walk.`,le=`Kofi here. If you can chat in full sentences, your pace is just right.`,q=(e,t,n,r,i={})=>({at:e,kind:`surge`,seconds:t,say:n,success:B,okay:V,recover:r,...i}),J=(e,t,n,r,i={})=>({at:e,kind:`surge`,seconds:t,say:n,success:H,okay:U,recover:r,...i}),Y=[...[{id:`first-steps`,title:`First Steps`,series:`intro`,type:`surge`,minutes:15,difficulty:`Gentle`,blurb:`Meet the Trailkeepers and slip past the cheeky Magpies twice.`,loop:`Close the loop to mark your first patch of ground for the crew.`,early:`Calling it there is fine. Welcome to the crew all the same. Your spot on the board is saved.`,beats:[{at:3,kind:`recover`,seconds:200,chapter:`Joining the crew`,say:`Kofi here on the radio. Welcome to the Trailkeepers. We look after this patch, one hex at a time. Start with an easy walk or jog.`},{at:60,kind:`story`,say:`Nan Bev runs the crew from her back verandah. She says g'day, and the kettle's on.`},{at:140,kind:`story`,say:`Tash is our lookout. She rides ahead on her bike and spots trouble before it spots us.`},{at:215,kind:`story`,chapter:`The Magpies`,say:`Uh oh. Tash has spotted the Magpies, a cheeky rival crew. They like to chalk their name on our hexes.`},q(245,30,`Dazza from the Magpies has seen you. Pick it up for 30 seconds to slip past him.`,120),{at:300,kind:`story`,say:`Ha. Dazza has stopped to retie his shoelace. Again.`},{at:380,kind:`story`,say:`Every street you run is ground the crew can hold. Close a loop and the hexes inside are ours.`},q(460,30,`One more. The Magpies are circling back. Pick it up for 30 seconds.`,120,{chapter:`Home stretch`}),{at:600,kind:`story`,say:`Nan Bev says you're a natural. High praise. She once told a surveyor his maps were wonky.`},{at:720,kind:`steady`,seconds:140,say:`Settle into an easy jog now. Nice and smooth. Let's head for the verandah.`,easyNudge:G},{at:870,kind:`finale`,say:`Mission complete. Welcome to the Trailkeepers. Nan Bev's put your name on the crew board.`}]},{id:`supply-line`,title:`Supply Line`,series:`intro`,type:`surge`,minutes:20,difficulty:`Gentle`,blurb:`Fetch supplies for the crew and keep the Magpies off the lamingtons.`,loop:`Close the loop to secure the supply line. That ground keeps the crew fed.`,early:`Good call stopping there. The supplies are safe at the halfway house, and the crew will fetch them later.`,beats:[{at:3,kind:`recover`,seconds:220,chapter:`The order`,say:`Kofi here. Big job today. The crew is low on supplies, and Nan Bev needs a run to the corner shop. Warm up with an easy jog.`},{at:70,kind:`story`,say:`The list says milk, a loaf of bread, and lamingtons. Nan Bev underlined lamingtons twice.`},{at:150,kind:`story`,say:`Tash says the shop is open and the Magpies are nowhere to be seen. So far.`},J(240,40,`The Magpies want the last lamingtons too. Pick it up for 40 seconds to beat them to the counter.`,120,{chapter:`The corner shop`}),{at:330,kind:`story`,say:`Got them. The shopkeeper says Dazza asked for lamingtons with no coconut. Whatever next.`},{at:420,kind:`story`,say:`Now for the long way home. Every hex you pass keeps the supply line open.`},q(510,40,`Dazza is following you with a very innocent look. Pick it up for 40 seconds to lose him.`,120,{chapter:`The supply line`}),{at:620,kind:`story`,say:`Stay smooth. The milk is fine. Probably.`},{at:700,kind:`steady`,seconds:180,say:`Hold an easy pace now. Scout the streets and keep the supply line clear.`,easyNudge:G},J(900,40,`Last push. Tash spotted Magpies near the verandah. Pick it up for 40 seconds to get the supplies home.`,150,{chapter:`Last leg`}),{at:1e3,kind:`story`,say:K},{at:1100,kind:`finale`,say:`Mission complete. The supplies made it, and Nan Bev has put the kettle on. The crew owes you a lamington.`}]},{id:`lantern-night`,title:`Lantern Night`,series:`intro`,type:`surge`,minutes:25,difficulty:`Gentle`,blurb:`Light a lantern on every hex before the street party starts.`,loop:`Close the loop and that whole patch glows for the party.`,early:`Stopping there is perfect. The lanterns you lit are glowing, and the party can start.`,beats:[{at:3,kind:`recover`,seconds:240,chapter:`Party prep`,say:`Kofi here. It's the street party tonight, and the Trailkeepers hang a lantern on every hex we hold. Warm up easy.`},{at:80,kind:`story`,say:`Nan Bev has made enough sausage rolls for the whole suburb. Twice.`},{at:170,kind:`story`,say:`Tash is counting lanterns. We need one for every hex. That's a lot of lanterns.`},J(260,45,`The Magpies are hanging their lanterns on our hexes. Pick it up for 45 seconds to get there first.`,150,{chapter:`The lantern run`}),{at:360,kind:`story`,say:`Lovely. That street's glowing in Trailkeeper green.`},{at:460,kind:`story`,say:`Kofi here. Breathe out long and slow. Your legs will thank you.`},J(540,45,`Dazza's crew is sneaking down the next street with a ladder. Pick it up for 45 seconds.`,150),{at:650,kind:`story`,say:`The Magpies have tangled their lantern string around a letterbox. We'll help them out later.`},{at:760,kind:`steady`,seconds:200,chapter:`Lights up`,say:`Easy pace now. Walk if you like. Take in the streets you've lit up.`,easyNudge:G},J(980,45,`Last lanterns. The party starts soon. Pick it up for 45 seconds to light the final hex.`,180),{at:1180,kind:`story`,say:`Hear that? The music has started, and the whole street is out.`},{at:1310,kind:`story`,say:`Nan Bev wants you to know there's a sausage roll with your name on it.`},{at:1440,kind:`finale`,say:`Mission complete. Every lantern is lit. Even Dazza came to the party, and he brought a pav. Fair play.`}]},{id:`magpie-season`,title:`Magpie Season`,series:`main`,type:`surge`,minutes:35,difficulty:`Steady effort`,blurb:`Swooping season. Six one minute surges to hold the park, a fartlek in disguise.`,loop:`Close the loop to hold the park. The Magpies hate that.`,early:`Fair enough. The ground you held today stays held, and the Magpies are still scratching their heads.`,beats:[{at:3,kind:`recover`,seconds:320,chapter:`Swooping season`,say:`Kofi here. It's swooping season, and the Magpies are out in force. Warm up easy for five minutes.`},{at:100,kind:`story`,say:`Spring does this to them. They get cheeky, they get loud, and they chalk their name on everything.`},{at:200,kind:`story`,say:`Nan Bev has a plan. Every time they swoop, you surge. Every time you surge, we hold the ground.`},q(330,60,`A Magpie scout has spotted you. Pick it up for 60 seconds to lose them.`,90,{chapter:`Six swoops`,half:W}),q(480,60,`Another swoop from the left. Pick it up for 60 seconds.`,90,{half:W}),q(630,60,`Here comes Dazza on his scooter. Pick it up for 60 seconds.`,90,{half:W}),{at:710,kind:`story`,say:`Kofi here. Arms relaxed, short quick steps. Lovely.`},q(780,60,`Halfway through the swoops. Pick it up for 60 seconds to hold the park.`,90,{half:W}),q(930,60,`Tash says two Magpies are hiding behind the bus shelter. Pick it up for 60 seconds.`,90,{half:W}),q(1080,60,`Last swoop. Pick it up for 60 seconds and we hold the lot.`,90,{half:W}),{at:1160,kind:`story`,say:`That's all six. The Magpies have gone quiet. Very suspicious.`},{at:1230,kind:`steady`,seconds:360,chapter:`Holding ground`,say:`Settle into an easy pace for a while. Scout the streets and let the crew catch up.`,easyNudge:G},{at:1420,kind:`story`,say:`Nan Bev says the Magpies have gone to the skate park to regroup.`},J(1600,30,`One last cheeky one. Pick it up for 30 seconds.`,60,{chapter:`Last laugh`}),J(1690,30,`And again, for luck. 30 seconds.`,240),{at:1780,kind:`story`,say:K},{at:1900,kind:`story`,say:`Kofi here. Have a big drink of water when you get home.`},{at:2040,kind:`finale`,say:`Mission complete. The ground is ours, and the Magpies sent a note. It says, see you next swooping season.`}]},{id:`hilltop-crown`,title:`The Hilltop Crown`,series:`main`,type:`surge`,minutes:40,difficulty:`Hard effort`,blurb:`Five 300 metre pushes and three quick bursts to win the crown at sunset.`,loop:`Close the loop to lock in the ground around the hill.`,early:`Smart to stop there. The ground you took today counts, and the crown will wait for a rematch.`,beats:[{at:3,kind:`recover`,seconds:320,chapter:`The challenge`,say:`Kofi here. The Magpies have challenged us for the hilltop crown. Most ground by sunset wears it. Warm up easy.`},{at:110,kind:`story`,say:`The crown is a bottle top on a string. Nan Bev made it years ago, and it means everything.`},{at:220,kind:`story`,say:`Tash has mapped it out. Five big pushes of about 300 metres. Recover well between them.`},q(330,null,`First push. Pick it up for 300 metres and plant our flag on the first hex.`,120,{metres:300,chapter:`Five pushes`,half:W}),q(550,null,`Second push. The Magpies are on the next street. Pick it up for 300 metres.`,120,{metres:300,half:W}),q(770,null,`Third push. Dazza is puffing, and so is his dog. Pick it up for 300 metres.`,120,{metres:300,half:W}),{at:920,kind:`story`,say:`Over halfway. Kofi here. Look ahead, not down.`},J(990,null,`Fourth push. Tash says the crown is in sight. Pick it up for 300 metres.`,120,{metres:300,half:W}),J(1210,null,`Final push. Pick it up for 300 metres and the hilltop is ours.`,180,{metres:300,half:W}),{at:1350,kind:`story`,say:`Breathe. That was big running.`},{at:1450,kind:`steady`,seconds:360,chapter:`Holding the hill`,say:`Easy pace now. Hold the ground and scout the streets around the hill.`,easyNudge:G},{at:1600,kind:`story`,say:`Kofi's checking the map. Our hexes are glowing all the way up the hill.`},{at:1760,kind:`story`,say:`The Magpies want one last contest. Three quick bursts, then the crown is decided.`},J(1850,60,`Burst one. Pick it up for 60 seconds.`,90,{chapter:`Sunset`,half:W}),J(2e3,60,`Burst two. Pick it up for 60 seconds.`,90,{half:W}),J(2150,60,`Last burst. Pick it up for 60 seconds, then the crown is decided.`,180,{half:W}),{at:2240,kind:`story`,say:K},{at:2320,kind:`story`,say:`Nan Bev is counting hexes. She counts slowly. Very slowly.`},{at:2400,kind:`finale`,say:`Mission complete. By Nan Bev's count, the hilltop crown is ours. Dazza shook your hand. Good sport, that one.`}]},{id:`steady-scout`,title:`Steady Scout`,series:`easy`,type:`steady`,minutes:20,difficulty:`Easy`,blurb:`No Magpies today. An easy run scouting the quiet streets for the crew.`,loop:`Close the loop to claim the streets you have scouted.`,early:`That was a fine scout. Every street you saw today is on the map now.`,beats:[{at:3,kind:`steady`,seconds:1140,chapter:`Quiet streets`,say:`Kofi here. No Magpies today, just quiet streets. Settle into an easy pace and scout the ground.`,easyNudge:G},{at:150,kind:`story`,say:`Your job is to look and listen. Which streets are quiet? Where would a loop fit?`},{at:300,kind:`story`,say:le},{at:450,kind:`story`,say:`Tash rode past and waved. She says the gardens on this street are looking lovely.`},{at:600,kind:`story`,chapter:`The far hexes`,say:`Halfway. The far hexes haven't seen a Trailkeeper in a while. They'll be glad of the visit.`},{at:750,kind:`story`,say:`Nan Bev says easy days build the engine. She's right, as usual.`},{at:900,kind:`story`,say:`Notice your shoulders. Keep them low and loose.`},{at:1050,kind:`story`,chapter:`Back to base`,say:`Start thinking about the way home. A loop back to your start claims what you've scouted.`},{at:1170,kind:`finale`,say:`Mission complete. The streets are scouted and the map is fresher for it. Lovely easy running.`}]}].map(e=>({saga:`trailkeepers`,...e})),...ae,...R],X=[{id:`trailkeepers`,title:`The Trailkeepers`,blurb:`A friendly crew, a cheeky rival and a suburb to hold.`,narrator:null,score:null},...ie,N],ue=e=>X.find(t=>t.id===e)||X[0],Z=[`first-steps`,`supply-line`,`lantern-night`,`magpie-season`,`hilltop-crown`],Q={trailkeepers:Z,...w,quiz:z},$=e=>Y.find(t=>t.id===e)||null;function de(e){for(let t of Object.values(Q)){let n=t.indexOf(e);if(n>0)return $(t[n-1])}return null}export{$ as a,X as i,Q as n,ue as o,Y as r,de as s,Z as t};